INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_INCONSISTENT_PROFILE', 'fp-PH', 'Nag-upload ng data o mga dokumento ng ibat ibang tao.
