INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_NOT_ALL_CHECKS_COMPLETED', 'fp-PH', 'Hindi nakumpleto ang lahat ng pagsusuri.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_NOT_DOCUMENT', 'fp-PH', 'Kumuha ng malinaw na larawan ng totoong dokumento at subukan ulit. Hindi tinatanggap ang larawan ng naka-print na dokumento.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_OK', 'fp-PH', 'Bumalik sa page ng pag-log in at subukang gawin ulit ang pag-verify sa ID.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_OTHER', 'fp-PH', 'Bumalik sa page ng pag-log in at subukang gawin ulit ang pag-verify sa ID.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_PEP', 'fp-PH', 'Pumalya ang pag-verify. Posibleng dahil ito sa seguridad o dahil pinaghihigpitan ang iyong bansa/rehiyon. Humihingi kami ng paumanhin sa anumang abalang idinulot nito.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_PROBLEMATIC_APPLICANT_DATA', 'fp-PH', 'Ibigay ang pangalan at apelyido/petsa ng kapanganakan/address na nakasulat sa dokumento.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_REGULATIONS_VIOLATIONS', 'fp-PH', 'Pumalya ang pag-verify. Posibleng dahil ito sa seguridad o dahil pinaghihigpitan ang iyong bansa/rehiyon. Humihingi kami ng paumanhin sa anumang abalang idinulot nito.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_REQUESTED_DATA_MISMATCH', 'fp-PH', 'Hindi tumutugma ang ibinigay na impormasyon sa data na natukoy mula sa dokumento.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SANCTIONS', 'fp-PH', 'Pumalya ang pag-verify. Posibleng dahil ito sa seguridad o dahil pinaghihigpitan ang iyong bansa/rehiyon. Humihingi kami ng paumanhin sa anumang abalang idinulot nito.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SCREENSHOTS', 'fp-PH', 'Hindi tinatanggap ang mga screenshot.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SELFIE_MISMATCH', 'fp-PH', 'Hindi tumutugma ang selfie sa larawan sa dokumento.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SELFIE_WITH_PAPER', 'fp-PH', 'Hindi sinusuportahan ang na-upload na selfie.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SPAM', 'fp-PH', 'Mga maling dokumento ang ibinigay.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNFILLED_ID', 'fp-PH', 'Hindi naglalaman ng mga pirma at stamp ang na-upload na dokumento.Bumalik sa page ng pag-log in at subukang gawin ulit ang pag-verify sa ID.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'fp-PH', 'Mga hindi kwalipikadong dokumento. Hindi mabasa or makita ang mga kinakailangang field ng dokumento. Mag-upload ng bagong larawan. Siguraduhing maliwanag at malinaw ang larawan at nakikita ang lahat ng sulok ng dokumento.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_ADDRESS', 'fp-PH', 'Hindi tumutugma ang address mula sa mga dokumento sa address na inilagay ng user.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'fp-PH', 'Paumanhin, hindi sinusuportahan ang rehiyon.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'fp-PH', 'Verify Income: Provide documentary evidence for all income sources declared with Binance, including salary, self-employment, pension, dividends, trading, rent, or other income. Submit sufficient and accurate supporting documents matching your declared income. Incorrect or insufficient information delays approval.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'fp-PH', 'Please provide a recent bank statement (issued within the last 3 months). It must contain your name, the issuer name/logo, and your transaction history, clearly showing monthly transfers from your employer, self-employed services, pension, allowances, dividends, trading or gambling profit withdrawals, rent or, any other transfers received on a regular basis that convey your full annual income declared with Binance. We prefer to receive these documents as a digital .pdf or full photos of physical statements.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'fp-PH', 'The uploaded documentary evidence does not clearly show an issuing date and cannot be accepted.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'fp-PH', 'You have uploaded documents where your personal details are not visible. Please ensure your full name, the date of issue, and any issuer logos are displayed on the supporting documentation.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'fp-PH', 'Your documentary evidence (issued with third-party names) cannot be accepted as your Source of Wealth or Source of Funds verification documentation. Please upload documents issued with your personal name or provide clarification on how the third-party documents can be used to verify your fiat activity or total asset worth.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'fp-PH', 'Dear Binancian, your application has been approved. Enjoy investing with Binance!', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'fp-PH', 'Before sending a Source of Wealth or a Source of Funds verification, please make sure you complete the identity verification process. You can complete the process by going to the identity verification tab and by uploading a valid passport or any other acceptable ID document, depending on the local requirements.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'fp-PH', 'Dear User, Binance has provided new fiat limits of 2 million USD per day for all of our user accounts. Your current limit increase request (for 500k/1 mil/2 mil USD) is deemed, therefore, unnecessary. Enjoy your trading!', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'fp-PH', 'Unfortunately, we were not able to verify your application with the provided evidence. In order to further assist you, we would like to invite you to a chat with our compliance department. In a few minutes you will receive an invitation email. Please click the “Chat Now” button to proceed.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'fp-PH', 'The uploaded documentary evidence is not clear enough and does not meet our visibility requirements. Please upload the original document. We prefer to receive these documents as a digital .pdf or full photos of physical statements with all four corners of the document visible.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'fp-PH', 'Please complete our PEP Declaration form with accurate responses. Please let us know if you are classified as a PEP or not, your full name, position, relationship (if you are a PEP by association), and for how long you have been a PEP. After providing this information, you can resubmit your application.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'fp-PH', 'Before sending a Source of Wealth or a Source of Funds verification, please make sure you complete the Proof of Address verification process. You can complete this process by going to the identity verification tab and by uploading a valid bank statement/utility bill/tax document, issued in the last three months, in your name, and with an accurate address visible.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'fp-PH', 'You have selected Allowance as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A bank statement showing allowance transfers for the last 3 months; 2) A government-issued allowance or other social benefits statement.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'fp-PH', 'You have declared that your source to funds is from the Sale of assets. Please provide a bank statement, showing the received payment into your bank account from the sale of your assets, with your name clearly shown and issuance date within 3 months of your application. We prefer to receive these documents as a digital .pdf or full photos of physical statements.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'fp-PH', 'You have declared that the funds in your account are derived from crypto mining activities. In order to support your application, please provide either: 1) Proof of purchase for the hardware used for mining (showing both yours and the sellers details); 2) Proof of all mining revenues from relevant platform(s)/exchange(s). In each case, we require screenshots for at least 3 months transaction history, detailing all activity with mined coins and displaying wallet addresses and transaction IDs. These must be taken from the relevant platform/exchange and include your account details.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'fp-PH', 'You have selected Day trading as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification:1) Transactions statements, proving your trading activity for the last month AND a bank statement, showing profit withdrawals deposited in your account. Both documents must show account registration details and the issuer logo; 2) A tax statement for the previous tax year, proving your income from trading profits.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'fp-PH', 'You have selected Dividends payments/Profit from a company as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Dividend statements; 2) Distribution agreements; 3) A bank statement showing dividend payments; 4) The most recent audit of company accounts.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'fp-PH', 'You have selected Donations as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A donation agreement for real estate or other assets; 2) A signed affidavit/letter from the donor declaring the nature of the gift; 3) A bank statement showing a bank deposit of the donation.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'fp-PH', 'You have selected Gambling as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification:1) Transactions statements, proving your gambling activity for the last month AND a bank statement, showing profit withdrawals deposited in your account. Both documents must show account registration details and the issuer logo; 2) A tax statement for the previous tax year, proving your income from gambling profits.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'fp-PH', 'You have selected Inheritance as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A copy of a will/testament; 2) A signed letter from the executor of the will (lawyer/solicitor/person given grant of probate).', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'fp-PH', 'You have selected Loans/Mortgages as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send the following to complete your verification: A Loan/mortgage contract, showing the loan amount and repayment plan AND a bank statement showing loan/mortgage deposits into your account.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'fp-PH', 'You have selected Passive income as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A signed rental/lease agreement AND one of the following: a. A bank statement, showing the latest rental/lease payment; b. The most recent rent/lease receipts; 2) Any other documents that prove your passive income (e.g. book royalties, affiliate marketing, staking etc.) for the last month.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'fp-PH', 'You have selected Pension as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A bank statement showing pension transfers for the last 3 months; 2) A government-issued pension statement; 3) Pension fund statements.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'fp-PH', 'You have selected Salary as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Payslips showing your income from at least the last month; 2) A bank statement showing salary payments from your employer for at least the last month; 3) A tax statement from the previous tax year.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'fp-PH', 'You have selected Sale of Financial assets as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A statement from your investment provider; 2) A bank statement displaying settlements from your investment provider; 3) Other statements or documents, proving investment profit from bonds, stocks, etc.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'fp-PH', 'You have selected Sale of Real estate or other assets as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A contract of sale/settlement statement; 2) A signed letter from a solicitor/lawyer/estate agent confirming the property sale; 3) Land registry/title deed copies. Additionally, you can send us a bank statement, showing the deposit of sale funds into your bank account.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'fp-PH', 'You have selected Savings as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a statement from a savings account (issued in the last 3 months).', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'fp-PH', 'You have selected Self-employment as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a tax statement from the previous tax year. Additionally, you can send us recent invoices/contracts/agreements for self-employed services or profit/loss statements, proving your monthly or annual income.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'fp-PH', 'You have selected Company profits (shares/dividends) as your Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Dividend statements; 2) Distribution agreements; 3) A bank statement showing dividend payments; 4) The most recent audit of company accounts.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'fp-PH', 'Verify Crypto Investment: Your provided evidence for Crypto as your main source of wealth is insufficient. Provide additional verification by submitting statements from other exchanges, screenshots of cold wallets, crypto purchase receipts, or any relevant documents. Ensure the provided evidence matches your declaration on our system.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'fp-PH', 'You have selected Donation as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A donation agreement for real estate or other assets; 2) A signed affidavit/letter from the donor declaring the nature of the gift; 3) A bank statement showing a bank deposit of the donation.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'fp-PH', 'You have selected Financial investment as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A statement from your investment provider; 2) A bank statement displaying settlements from your investment provider; 3) Other statements or documents, proving investment profit from bonds, stocks, etc.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'fp-PH', 'You have selected Inheritance as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A copy of a will/testament; 2) A signed letter from the executor of the will (lawyer/solicitor/grant of probate).', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'fp-PH', 'You have selected Mortgages/Loans as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send the following to complete your verification: A Mortgage/Loan contract, showing the mortgage or loan value and repayment plan AND a bank statement showing the loan/mortgage deposit into your account.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'fp-PH', 'You have selected Salary as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Payslips showing your income from at least the last month; 2) A bank statement showing salary payments from your employer for at least the last month; 3) A tax statement from the previous tax year.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'fp-PH', 'You have selected Self-employment as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a tax statement from the previous tax year. Additionally, you can send us recent invoices/contracts/agreements for self-employed services or profit/loss statements, proving your monthly or annual income.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'fp-PH', 'We have identified a discrepancy in your overall wealth declaration. The documentary evidence provided indicates a significantly higher Total Assets value and does not correspond to the one you have declared with Binance. Please provide us with accurate information for your overall (approximate) total value of all owned assets and submit your application again. Providing incorrect, insufficient, or misleading information prevents the prompt approval of your application.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'fp-PH', 'After reviewing your declaration, we found significant errors. To ensure a speedy process, provide accurate and complete data for your annual income (gross), total assets, and sources of wealth. Please submit adequate evidence alongside your declaration. Incorrect or insufficient information will delay your application. Thank you for your cooperation.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'fp-PH', 'We have identified incorrect, mismatching, or incomplete information on your Employment details declaration. Please resubmit your application with accurate information, including: 1) Employment status - current Employed/Self-employed/Student/Retired/Other status; 2) Employer/Business name - the name of your Employers Company/Business name; 3) Employer/Business address - registered Employer/Business address. Please ensure the information provided is up-to-date and that it matches the information provided in your documentary evidence.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'fp-PH', 'We have noticed the transfer of funds from your other bank account. Please send us a bank statement issued in the last 3 months, showing the transaction history of the other account (covering at least 1 month of transactions).', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'fp-PH', 'The image quality of your photo is not clear and does not meet our visibility requirements. Please resubmit a copy in a higher resolution (at least 300 DPI) showing the full page with all four corners included in the frame. Alternatively, you can provide different documents to complete your verification.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_SELFIE', 'fp-PH', 'Uploaded poor quality selfie. Please go back to the login page and try to do the ID verification again.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_COMPANY_NOT_VALIDATED_REPRESENTATIVES', 'fp-PH', 'Representatives cannot be validated. Please go back to the login page and try to do the ID verification again.', '2023-06-18 18:48:28', '2023-06-18 18:48:28') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'fr-FR', 'Vérifiez les revenus : fournissez des documents justificatifs pour toutes les sources de revenus déclarées à Binance, dont le salaire, le travail indépendant, la pension, les dividendes, le trading, le loyer ou d’autres revenus. Envoyez des documents justificatifs suffisants et exacts correspondant aux revenus déclarés. Des informations incorrectes ou insuffisantes retardent l’approbation.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'fr-FR', 'Veuillez fournir un relevé bancaire récent (émis au cours des trois derniers mois). Celui-ci doit contenir votre nom, le nom/logo de l’émetteur, et l’historique de vos transactions, indiquant clairement les transferts mensuels de votre employeur, les services non salariés, pensions, allocations, dividendes, retraits de gains de trading ou de jeu, loyer ou, tout autre transfert reçu sur une base régulière qui traduit votre revenu annuel complet déclaré auprès de Binance. Nous préférons recevoir ces documents au format numérique .pdf ou des photos complètes des déclarations physiques.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'fr-FR', 'La pièce justificative téléchargée n’indique pas clairement une date de délivrance et ne peut être acceptée.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'fr-FR', 'Vous avez téléchargé des documents sur lesquels vos détails personnels ne sont pas visibles. Veuillez vous assurer que votre nom complet, la date de délivrance et tout logo de l’émetteur figurent sur les documents justificatifs.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'fr-FR', 'Vos documents justificatifs (émis avec des noms de tiers) ne peuvent pas être acceptés comme documents de vérification de l’origine du patrimoine financier ou de l’origine des fonds. Veuillez télécharger les documents émis à votre nom personnel ou fournir des précisions sur la manière dont les documents de tiers peuvent être utilisés pour vérifier votre activité en devises fiat ou la valeur totale de vos actifs.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'fr-FR', 'Cher Binancien, Chère Binancienne, votre demande a été approuvée. Profitez de votre investissement avec Binance !', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'fr-FR', 'Avant d’envoyer une vérification de l’origine du patrimoine financier ou de l’origine des fonds, veuillez vous assurer que vous avez terminé le processus de vérification de l’identité. Vous pouvez compléter le processus en vous rendant sur l’onglet de vérification de l’identité et en téléchargeant un passeport valide ou toute autre pièce d’identité acceptable, selon les réglementations locales.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'fr-FR', 'Cher utilisateur, chère utilisatrice, Binance a mis en place une nouvelle limite de devise(s) fiat de deux millions USD par jour pour l’ensemble de nos comptes utilisateurs. Votre demande actuelle d’augmentation des limites (pour 500 000/1 million/2 millions USD) est donc jugée inutile. Profitez de votre trading !', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'fr-FR', 'Malheureusement, nous n’avons pas été en mesure de vérifier votre demande avec les preuves fournies. Afin de mieux vous aider, nous vous invitons à un chat avec notre service de conformité. Dans quelques minutes, vous recevrez un e-mail d’invitation. Veuillez cliquer sur le bouton « Participer au chat maintenant » pour continuer.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'fr-FR', 'Les documents justificatifs téléchargés ne sont pas assez clairs et ne répondent pas à nos exigences de visibilité. Veuillez télécharger le document original. Nous préférons recevoir ces documents au format numérique .pdf ou des photos complètes des déclarations physiques avec les quatre coins du document visibles.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'fr-FR', 'Veuillez remplir notre formulaire de déclaration PPE avec des réponses exactes. Veuillez nous indiquer si vous êtes classé comme une PPE ou non, votre nom complet, votre fonction, votre relation (si vous êtes une PPE par association), et depuis combien de temps vous êtes une PPE. Après avoir fourni ces informations, vous pouvez soumettre à nouveau votre demande.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'fr-FR', 'Avant d’envoyer une vérification de l’origine du patrimoine financier ou de l’origine des fonds, veuillez vous assurer que vous avez terminé le processus de vérification de la preuve d’adresse. Vous pouvez compléter ce processus en vous rendant sur l’onglet de vérification de l’identité et en téléchargeant un relevé bancaire/une facture d’eau, d’électricité, de gaz, etc./un document fiscal valide, émis au cours des trois derniers mois, à votre nom et avec une adresse exacte visible.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'fr-FR', 'Vous avez choisi l’allocation comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un relevé bancaire indiquant les transferts d’allocations pour les trois derniers mois ; 2) Un relevé d’allocations ou d’autres prestations sociales délivré par le gouvernement.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'fr-FR', 'Vous avez déclaré que votre origine des fonds provient de la vente d’actifs Veuillez fournir un relevé bancaire, indiquant le paiement reçu sur votre compte bancaire à la suite de la vente de vos actifs, avec votre nom clairement indiqué et la date de délivrance dans les trois mois suivant votre demande. Nous préférons recevoir ces documents au format numérique .pdf ou des photos complètes des déclarations physiques.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'fr-FR', 'Vous avez déclaré que les fonds de votre compte proviennent d’activités de minage de cryptos. Afin d’appuyer votre demande, veuillez fournir soit : 1) Une preuve d’achat du matériel utilisé pour le minage (indiquant à la fois vos coordonnées et celles du/de la vendeur/vendeuse) ; 2) Une preuve de tous les revenus du minage provenant de la (des) plateforme(s)/exchange(s) concerné(es). Dans chaque cas, nous exigeons des captures d’écran de l’historique des transactions sur au moins trois mois, détaillant toute activité avec des cryptos minées et affichant les adresses des portefeuilles et les identifiants des transactions. Celles-ci doivent provenir de la plateforme/de l’exchange concerné(e) et inclure les détails de votre compte.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'fr-FR', 'Vous avez choisi le day trading comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des relevés de transactions, prouvant votre activité de trading pour le mois dernier ET un relevé bancaire, montrant les retraits des gains déposés sur votre compte. Les deux documents doivent indiquer les détails de l’enregistrement du compte et le logo de l’émetteur ; 2) Une déclaration d’impôt pour l’année fiscale précédente, prouvant vos revenus provenant de gains de trading.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'fr-FR', 'Vous avez choisi les paiements de dividendes/gains provenant dune entreprise comme principales origines des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des relevés de dividendes ; 2) Les accords de distribution ; 3) Un relevé bancaire indiquant les paiements de dividendes ; 4) L’audit le plus récent des comptes de l’entreprise.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'fr-FR', 'Vous avez choisi les donations comme principales origines des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un contrat de donation pour des biens immobiliers ou d’autres actifs ; 2) Une déclaration sous serment/une lettre signée du donateur déclarant la nature du don ; 3) Un relevé bancaire indiquant un dépôt bancaire du don.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'fr-FR', 'Vous avez choisi les jeux comme principales origines des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des relevés de transactions, prouvant votre activité de trading pour le mois dernier ET un relevé bancaire, montrant les retraits des gains déposés sur votre compte. Les deux documents doivent indiquer les détails de l’enregistrement du compte et le logo de l’émetteur ; 2) Une déclaration d’impôt pour l’année fiscale précédente, prouvant vos revenus provenant de gains de jeux.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'fr-FR', 'Vous avez choisi l’héritage comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Une copie du testament ; 2) Une lettre signée de l’exécuteur testamentaire (avocat/solliciteur/personne à qui l’homologation a été accordée).', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'fr-FR', 'Vous avez choisi les prêts/hypothèques comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez envoyer les documents suivants pour compléter votre vérification : Un contrat de prêt/hypothèque, indiquant le montant du prêt et le plan de remboursement ET un relevé bancaire indiquant les dépôts du prêt/hypothèque sur votre compte.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'fr-FR', 'Vous avez choisi le revenu passif comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un contrat de location signé ET l’un des documents suivants : a. Un relevé bancaire indiquant le dernier paiement d’un loyer/d’une location ; b. Les dernières quittances de loyer/location ; 2) Tout autre document prouvant votre revenu passif (par ex. : les redevances de livres, de marketing d’affiliation, staking, etc.) pour le mois dernier.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'fr-FR', 'Vous avez choisi la pension comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un relevé bancaire indiquant les transferts de pension pour les trois derniers mois ; 2) Un relevé de pension émis par le gouvernement ; 3) Des relevés de fonds de pension.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'fr-FR', 'Vous avez choisi le salaire comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des fiches de paie indiquant vos revenus pour au moins le mois dernier ; 2) Un relevé bancaire indiquant les paiements de salaire de votre employeur depuis au moins le mois dernier ; 3) Un relevé d’imposition de l’année fiscale précédente.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'fr-FR', 'Vous avez choisi la vente dactifs financiers comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un relevé de votre fournisseur de services d’investissement ; 2) Un relevé bancaire indiquant les règlements de votre fournisseur de services d’investissement ; 3) D’autres relevés ou documents, prouvant le gain de l’investissement en obligations, actions, etc.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'fr-FR', 'Vous avez choisi la vente dactifs financiers comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un contrat de vente/déclaration de règlement ; 2) Une lettre signée par un avocat/un notaire/un agent immobilier confirmant la vente de la propriété ; 3) Des copies du registre foncier/du titre de propriété. En outre, vous pouvez nous envoyer un relevé bancaire indiquant le dépôt des fonds de la vente sur votre compte bancaire.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'fr-FR', 'Vous avez choisi lépargne comme principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un relevé de compte d’épargne (émis au cours des trois derniers mois).', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'fr-FR', 'Vous avez choisi le travail indépendant comme votre principale origine des fonds, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un relevé d’imposition de l’année fiscale précédente. En outre, vous pouvez nous envoyer des factures/contrats/accords récents pour des services non salariés que vous proposez ou des déclarations de gains/pertes, prouvant votre revenu mensuel ou annuel.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'fr-FR', 'Vous avez choisi les gains de l’entreprise (actions/dividendes) comme principales origines du patrimoine, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des relevés de dividendes ; 2) Les accords de distribution ; 3) Un relevé bancaire indiquant les paiements de dividendes ; 4) L’audit le plus récent des comptes de l’entreprise.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'fr-FR', 'Vérifiez l’investissement crypto : les preuves que vous avez fournies pour démontrer que les cryptomonnaies sont à l’origine du patrimoine financier sont insuffisantes. Fournissez une vérification supplémentaire en soumettant des déclarations d’autres échanges, des captures d’écran de portefeuilles hors ligne, des reçus d’achat de cryptomonnaies ou tout autre document pertinent. Assurez-vous que les preuves fournies correspondent à votre déclaration dans notre système.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'fr-FR', 'Vous avez choisi les donations comme principales origines du patrimoine, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un contrat de donation pour des biens immobiliers ou d’autres actifs ; 2) Une déclaration sous serment/une lettre signée du donateur déclarant la nature du don ; 3) Un relevé bancaire indiquant un dépôt bancaire du don.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'fr-FR', 'Vous avez choisi linvestissement financier comme principale origine du patrimoine financier, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Un relevé de votre fournisseur de services d’investissement ; 2) Un relevé bancaire indiquant les règlements de votre fournisseur de services d’investissement ; 3) D’autres relevés ou documents, prouvant le gain de l’investissement en obligations, actions, etc.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'fr-FR', 'Vous avez choisi l’héritage comme principale origine du patrimoine financier, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Une copie du testament ; 2) Une lettre signée de l’exécuteur testamentaire (avocat/solliciteur/agent d’homologation).', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'fr-FR', 'Vous avez choisi les hypothèques/prêts comme principales origines du patrimoine, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez envoyer les documents suivants pour compléter votre vérification : Un contrat d’hypothèque/de prêt, indiquant la valeur de l’hypothèque ou du prêt et le plan de remboursement ET un relevé bancaire indiquant le dépôt du prêt/de l’hypothèque sur votre compte.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'fr-FR', 'Vous avez choisi le salaire comme principale origine du patrimoine, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un ou plusieurs des documents suivants pour compléter votre vérification : 1) Des fiches de paie indiquant vos revenus pour au moins le mois dernier ; 2) Un relevé bancaire indiquant les paiements de salaire de votre employeur depuis au moins le mois dernier ; 3) Un relevé d’imposition de l’année fiscale précédente.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'fr-FR', 'Vous avez choisi le travail indépendant comme votre principale origine du patrimoine financier, mais les documents justificatifs fournis ne sont pas suffisants et ne répondent pas à nos exigences. Veuillez nous envoyer un relevé d’imposition de l’année fiscale précédente. En outre, vous pouvez nous envoyer des factures/contrats/accords récents pour des services non salariés que vous proposez ou des déclarations de gains/pertes, prouvant votre revenu mensuel ou annuel.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'fr-FR', 'Nous avons identifié une anomalie dans votre déclaration de patrimoine global. Les pièces justificatives fournies indiquent une valeur totale des actifs nettement supérieure et ne correspondent pas à celle que vous avez déclarée auprès de Binance. Veuillez nous fournir des informations précises sur la valeur totale (approximative) de tous les actifs que vous possédez et soumettre à nouveau votre demande. Fournir des informations incorrectes, insuffisantes ou trompeuses empêche l’approbation rapide de votre demande.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'fr-FR', 'Après avoir examiné votre déclaration, nous avons trouvé des erreurs significatives. Pour garantir une procédure rapide, fournissez des données précises et complètes sur votre revenu annuel (brut), votre patrimoine total et l’origine du patrimoine financier. Veuillez joindre des preuves adéquates à votre déclaration. Des informations incorrectes ou insuffisantes retarderont votre demande. Nous vous remercions pour votre coopération.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'fr-FR', 'Nous avons identifié des informations incorrectes, non concordantes ou incomplètes sur votre déclaration fournissant des détails sur votre emploi. Veuillez soumettre à nouveau votre demande avec des informations exactes, notamment : 1) Le statut d’emploi : statut actuel d’employé/travailleur indépendant/étudiant/retraité/autre ; 2) Le nom de l’employeur/de l’entreprise : nom de la société/de l’entreprise de votre employeur ; 3) L’adresse de l’employeur/de l’entreprise : adresse enregistrée de l’employeur/de l’entreprise. Veuillez vous assurer que les informations fournies sont à jour et qu’elles correspondent aux informations fournies dans vos documents justificatifs.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'fr-FR', 'Nous avons remarqué le transfert de fonds depuis votre autre compte bancaire. Veuillez nous envoyer un relevé bancaire émis au cours des trois derniers mois, indiquant l’historique des transactions de l’autre compte (couvrant au moins un mois de transactions).', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'fr-FR', 'La qualité de l’image de votre photo n’est pas lisible et ne répond pas à nos exigences de visibilité. Veuillez soumettre à nouveau une copie dans une résolution supérieure (au moins 300 DPI) montrant la page entière avec les quatre coins inclus dans le cadre. Vous pouvez également fournir différents documents pour compléter votre vérification.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADDITIONAL_DOCUMENT_REQUIRED', 'fr-FR', 'Documents supplémentaires requis pour passer la vérification.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'fr-FR', 'Échec de la vérification. Cela peut être dû à des raisons de sécurité ou à des restrictions imposées à votre pays/région. Nous vous prions de nous excuser pour la gêne occasionnée.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'fr-FR', 'Désolé, nous n’avons pas pu vérifier votre profil car votre âge ne correspond pas aux exigences. Si votre date de naissance (âge) répond à cette exigence, veuillez prendre une photo claire et réessayer.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BACK_SIDE_MISSING', 'fr-FR', 'Le verso du document est manquant.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_AVATAR', 'fr-FR', 'Veuillez retourner à la page de connexion et essayez à nouveau d’effectuer la vérification d’identité.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
