INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_SELFIE', 'fr-FR', 'Selfie de mauvaise qualité téléchargé. Veuillez retourner à la page de connexion et essayez à nouveau d’effectuer la vérification d’identité.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
