INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BLACKLIST', 'fr-FR', 'Échec de la vérification. Cela peut être dû à des raisons de sécurité ou à des restrictions imposées à votre pays/région. Nous vous prions de nous excuser pour la gêne occasionnée.', '2023-06-18 18:48:29', '2023-06-18 18:48:29') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
