INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_COMPANY_NOT_DEFINED_REPRESENTATIVES', 'fr-FR', 'Les représentants ne sont pas définis.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_COMPANY_NOT_DEFINED_STRUCTURE', 'fr-FR', 'La structure de contrôle de l’entité n’a pas pu être établie.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_COMPANY_NOT_VALIDATED_BENEFICIARIES', 'fr-FR', 'Les bénéficiaires ne sont pas acceptés.
