INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'ka-GE', 'დაადასტურეთ შემოსავალი: დოკუმენტის ფორმით წარმოადგინეთ Binance-ზე შემოსავლის ყველა წყაროს მტკიცებულება, რაც მოიცავს ანაზღაურებას, თვითმომსახურებას, პენსიას, დივიდენდებს, ვაჭრობას, ქირას ან სხვა შემოსავალს. საკმარისი ოდენობითა და საჭირო სიზუსტით წარადგინეთ თქვენ მიერ დეკლარირებული შემოსავლის შესაბამისი დამხმარე დოკუმენტები. არასწორი ან არასაკმარისი ინფორმაციის წარდგენა გააჭიანურებს თქვენი განაცხადის დადასტურებას.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'ka-GE', 'მოგვაწოდეთ უახლესი საბანკო ამონაწერი (ბოლო სამი თვის პერიოდისთვის). მასში მოცემული უნდა იყოს თქვენი სახელი, გამცემის სახელწოდება/ლოგო და ტრანზაქციების ისტორია, ყოველთვიური გადმორიცხვები დამსაქმებლისგან, თვითდასაქმების სერვისებიდან, პენსია, შემწეობა, დივიდენდები, ვაჭრობის ან აზარტული თამაშებიდან მიღებული სარგებლის გატანა, ქირა ან სხვა რეგულარული გადარიცხვა, რომელიც Binance-ზე მითითებულ წლიურ შემოსავალს შეესაბამება. დოკუმენტაციის ჩვენთვის მისაღები ფორმა არის ციფრული .pdf ფორმატი ან ფიზიკური ამონაწერების სრული ფოტოები.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'ka-GE', 'ატვირთულ დოკუმენტურ მტკიცებულებაზე არ ჩანს გაცემის თარიღი, ამიტომ მისი მიღება შეუძლებელია.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'ka-GE', 'თქვენ მიერ ატვირთულ დოკუმენტაციაზე პირადი დეტალების ამოკითხვა ვერ მოხერხდა. დარწმუნდით რომ დოკუმენტებზე ჩანს თქვენი სრული სახელი, გაცემის თარიღი და გამცემის ლოგო.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'ka-GE', 'თქვენი დოკუმენტური მტკიცებულება (მესამე მხარის სახელებთან ერთად) ვერ იქნება მიღებული ფინანსების წყაროს ან ქონების წყაროს ვერიფიკაციის დოკუმენტაციად. ატვირთეთ თქვენს სახელზე გაცემული დოკუმენტაცია ან წარმოადგინეთ ახლა როგორ უნდა გამოვიყენოთ მესამე პირის სახელზე გაცემული დოკუმენტები თქვენი ფიატ საქმიანობის ან აქტივების ღირებულების ვერიფიკაციისთვის.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'ka-GE', 'ძვირფასო Binance-ის მომხმარებელო, თქვენი განაცხადი დადასტურებულია. Binance-ზე წარმატებულ ინვესტირებას გისურვებთ!', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'ka-GE', 'ფინანსების წყაროს ან ქონების წყაროს ვერიფიკაციის გამოგზავნამდე, დარწმუნდით რომ ვინაობის ვერიფიკაცია უკვე გაიარეთ. პროცესის დასასრულებლად გადადით ვინაობის ვერიფიკაციის ჩანართზე და ატვირთეთ ვალიდური პასპორტი ან სხვა მისაღები ID დოკუმენტი ადგილობრივი მოთხოვნების მიხედვით.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'ka-GE', 'ძვირფასო მომხმარებელი, Binance ყველა მომხმარებელს ყოველდღიურ 2 მილიონ დოლარიან ფიატის ლიმიტს სთავაზობს. შესაბამისად, თქვენი მოთხოვნა მიმდინარე ლიმიტის გაზრდის შესახებ (500000 დოლარიდან/1 მლნ/2 მლნ დოლარამდე) აღარ არის საჭირო. სასიამოვნო ვაჭრობას გისურვებთ!', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'ka-GE', 'სამწუხაროდ თქვენ მიერ მოწოდებული მტკიცებულებებით განაცხადის ვერიფიკაცია ვერ მოხერხდა. გიწვევთ ჩვენი შესაბამისობის დეპარტამენტის ჩათში, რათა შევძლოთ უკეთ დახმარება. რამდენიმე წუთში ელ. ფოსტით მოწვევას მიიღებთ. გასაგრძელებლად დააწკაპუნეთ ღილაკზე „ჩათის დაწყება“.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'ka-GE', 'ატვირთული დოკუმენტური მტკიცებულების ხარისხი დაბალია და არ შეესაბამება ჩვენს გარჩევადობის მოთხოვნებს. ატვირთეთ ორიგინალი დოკუმენტის ფოტო. დოკუმენტაციის ჩვენთვის მისაღები ფორმა არის ციფრული .pdf ფორმატი თქვენი ფოტოებისა და ფიზიკური განცხადებებისთვის ისე, რომ დოკუმენტის ოთხივე კუთხე ჩანდეს.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'ka-GE', 'სწორად შეავსეთ ჩვენი პოლიტიკურად მნიშვნელოვანი პირის დეკლარაციის ფორმა. შეგვატყობინეთ კლასიფიცირდებით თუ არა პოლიტიკურად მნიშვნელოვანი ფიგურად, თქვენი სრული სახელი, თანამდებობა, ურთიერთობა (ხართ თუ არა პოლიტიკურად მნიშვნელოვანი ფიგურის ახლობელი) და რამდენი ხანია, რაც პოლიტიკურად მნიშვნელოვანი ფიგურა ხართ. ამ ინფორმაციის მოწოდების შემდეგ შეგიძლიათ განაცხადი თავიდან წარადგინოთ.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'ka-GE', 'ფინანსების წყაროს ან ქონების წყაროს ვერიფიკაციის გამოგზავნამდე, დარწმუნდით რომ ვინაობის ვერიფიკაცია უკვე გაიარეთ. პროცესის დასასრულებლად გადადით ვინაობის ვერიფიკაციის ჩანართზე და ატვირთეთ ვალიდური საბანკო ამონაწერი/კომუნალური გადასახადების ქვითარი/საგადასახადო დოკუმენტი, რომელიც თქვენს სახელზე გაცემულია ბოლო სამი თვის განმავლობაში და ჩანს ზუსტი მისამართი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ შემწეობა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად გამოგვიგზავნეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) საბანკო ამონაწერი, სადაც ნაჩვენებია ბოლო სამი თვის პენსიების ჩარიცხვა; 2) მთავრობის გაცემული განაცხადი პენსიის შესახებ; 3) საპენსიო ფონდის განაცხადი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'ka-GE', 'განაცხადის მიხედვით, თქვენი ფინანსების წყარო აქტივების გაყიდვაა. მოგვაწოდეთ საბანკო ამონაწერი, სადაც ნაჩვენებია თქვენს საბანკო ანგარიშზე აქტივების გაყიდვის შედეგად ჩარიცხული თანხა, გარკვევით იკითხება თქვენი სახელი და გაცემულია განაცხადის გაკეთებამდე სამი თვის ვადაში. დოკუმენტაციის ჩვენთვის მისაღები ფორმა არის ციფრული .pdf ფორმატი ან ფიზიკური ამონაწერების სრული ფოტოები.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'ka-GE', 'განაცხადის მიხედვით, თქვენი ფინანსების წყარო არის კრიპტო მაინინგი. თქვენი განაცხადის დასადასტურებლად, მოგვაწოდეთ ერთ-ერთი: 1) მაინინგისთვის სჭირო აპარატურის შესყიდვის მტკიცებულება (რომელზეც ნაჩვენებია თქვენი და გამყიდველის სახელი); 2) მაინინგით მიღებული შემოსავლის მტკიცებულება შესაბამისი პლატფორმ(ებ)იდან/ბირჟ(ებ)იდან. ნებისმიერ შემთხვევაში უნდა მოგვაწოდოთ ეკრანის ანაბეჭდი, რომელზეც ნაჩვენებია ბოლო სამი თვის ტრანზაქციების ისტორია შექმნილი მონეტების დეტალებით, საფულის მისამართებით და ტრანზაქციის ID-ებით. ეკრანის ანაბეჭდები უნდა ასახავდეს შესაბამის პლატფორმას/ბირჟას და შეიცავდეს თქვენი ანგარიშის დეტალებს.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ დეი-ტრეიდინგი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) ტრანზაქციების ამონაწერები, რომლებიც ადასტურებს თქვენს ბოლო თვის სავაჭრო აქტივობას და საბანკო ამონაწერი, რომელიც აჩვენებს თქვენს საბანკო ანგარიშზე შეტანილი მოგების გატანას. ორივე დოკუმენტზე უნდა ჩანდეს ანგარიშის რეგისტრაციის დეტალები და გამცემის ლოგო; 2) ასული საგადასახადო წლის საგადასახადო ამონაწერი, რომელიც ადასტურებს თქვენი ვაჭრობის მოგებისგან მიღებულ შემოსავალს.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ დივიდენდები/სარგებელი კომპანიისგან, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) დივიდენდის ამონაწერები; 2) განაწილების ხელშეკრულებები; 3) საბანკო ამონაწერი, სადაც ნაჩვენებია დივიდენდების გადახდები; 4) უახლესი აუდიტირებული კომპანიის ანგარიშები.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ დონაცია, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) დონაციის შეთანხმება უძრავი ქონების ან სხვა აქტივის შესახებ; 2) ხელმოწერილი აფიდევიტი/წერილი დონორისგან საჩუქრის ტიპის მითითებით; 3) საბანკო ამონაწერი, სადაც ნაჩვენებია დონაციის საბანკო დეპოზიტი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ აზარტული თამაშები, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) ტრანზაქციების ამონაწერები, რომლებიც ადასტურებს თქვენს ბოლო თვის სავაჭრო აქტივობას და საბანკო ამონაწერი, რომელიც აჩვენებს თქვენს საბანკო ანგარიშზე შეტანილი მოგების გატანას. ორივე დოკუმენტზე უნდა ჩანდეს ანგარიშის რეგისტრაციის დეტალები და გამცემის ლოგო; 2) ასული საგადასახადო წლის საგადასახადო ამონაწერი, რომელიც ადასტურებს თქვენი ვაჭრობის მოგებისგან მიღებულ შემოსავალს.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ მემკვიდრეობა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ერთი ან რამდენიმე ქვემოთ მითითებული დოკუმენტი: 1) უკანასკნელი ნების/ანდერძის ასლი 2) ანდერძის აღმასრულებლის (ადვოკატის/სოლისიტორის/ნდობით აღჭურვილი პირის) მიერ მომზადებული და ხელმოწერილი წერილი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ სესხი/იპოთეკა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: იპოთეკის/სესხის ხელშეკრულება, სადაც ნაჩვენებია იპოთეკის ან სესხის ღირებულება დაფარვის გეგმით და საბანკო ამონაწერი, სადაც ნაჩვენებია სესხის/იპოთეკის დეპოზიტს თქვენს ანგარიშზე.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ პასიური შემოსავალი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) ქირის/იჯარის ხელმოწერილი ხელშეკრულება და ერთ-ერთი: ა. საბანკო ამონაწერი, რომელიც აჩვენებს უახლეს ქირის/იჯარის გადახდას; ბ. ქირავნობის/იჯარის უახლესი ქვითრები; 2) ნებისმიერი სხვა დოკუმენტი, რომელიც ამტკიცებს თქვენს პასიურ შემოსავალს (მაგ. წიგნის ჰონორარი, პარტნიორული მარკეტინგი, სტეიკინგი და ა.შ.) გასული თვის განმავლობაში.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ პენსია, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად გამოგვიგზავნეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) საბანკო ამონაწერი, სადაც ნაჩვენებია ბოლო სამი თვის პენსიების ჩარიცხვა; 2) მთავრობის გაცემული განაცხადი პენსიის შესახებ; 3) საპენსიო ფონდის განაცხადი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ ხელფასი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) სახელფასო ამონაწერები, სადაც ნაჩვენებია თქვენი შემოსავალი მინიმუმ ბოლო თვის განმავლობაში; 2) საბანკო ამონაწერი, სადაც ნაჩვენებია ხელფასის ჩარიცხვა დამსაქმებლისგან მინიმუმ ბოლო თვის განმავლობაში; 3) გასული წლის საგადასახადო ამონაწერი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ ფინანსური აქტივებით ვაჭრობა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) განაცხადი ინვესტიციის მომწოდებლისგან; 2) საბანკო ამონაწერი, სადაც ნაჩვენებია ინვესტიციის მომწოდებელთან ანგარიშსწორება; 3) სხვა ამონაწერები ან დოკუმენტები, რომლებიც ამტკიცებს საინვესტიციო მოგებას ობლიგაციებიდან, აქციებიდან და ა.შ.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ უძრავი ქონების გაყიდვა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) გაყიდვის კონტრაქტი/ანგარიშსწორების განაცხადი; 2) შუამავლის/ადვოკატის/ ქონების აგენტის ხელმოწერილი წერილი ქონების გაყიდვის დადასტურების შესახებ; 3) მიწის რეესტრის/საკუთრების დამადასტურებელი დოკუმენტების ასლები. გარდა ამისა, თქვენ ასევე შეგიძლიათ გამოგვიგზავნოთ საბანკო ამონაწერი, რომელშიც ნაჩვენები იქნება თანხის დეპოზიტი თქვენს საბანკო ანგარიშზე', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ დანაზოგი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. მოგვაწოდეთ ამონაწერი დანაზოგების ანგარიშიდან (გაცემული ბოლო 3 თვის პერიოდში).', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'ka-GE', 'ფინანსების მთავარ წყაროდ მითითებული გაქვთ თვითდასაქმება, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. გამოგვიგზავნეთ გასული საგადასახადო წლის საგადასახადო ამონაწერი. დამატებით მომხმარებლებს შეუძლიათ გამოგვიგზავნონ უახლესი ინვოისები/კონტრაქტები/შეთანხმებები თვითდასაქმებული სერვისებისთვის ან მოგება/ზარალის ანგარიშგება, რომელიც ადასტურებს ყოველთვიურ ან წლიურ შემოსავალს', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ კომპანიის მოგება (წილები/დივიდენდები) თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) დივიდენდის ამონაწერები; 2) განაწილების ხელშეკრულებები; 3) საბანკო ამონაწერი, სადაც ნაჩვენებია დივიდენდების გადახდები; 4) უახლესი აუდიტირებული კომპანიის ანგარიშები.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'ka-GE', 'დაადასტურეთ თქვენი კრიპტო ინვესტიცია: კრიპტოს, როგორც თქვენი შემოსავლის მთავარი წყაროს შესახებ თქვენ მიერ წარმოდგენილი მტკიცებულება არ არის საკმარისი. წარმოადგინეთ დამატებითი დამადასტურებელი მტკიცებულება, მაგალითად სხვა ბირჟებიდან ამონაწერები, ცივი საფულეების ეკრანის ანაბეჭდები, კრიპტოს შეძენის ქვითრები და სხვა შესაბამისი დოკუმენტები. დარწმუნდით, რომ წარმოდგენილი მტკიცებულებები ემთხვევა ჩვენს სისტემაში თქვენს დეკლარაციას.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ დონაცია, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) დონაციის შეთანხმება უძრავი ქონების ან სხვა აქტივის შესახებ; 2) ხელმოწერილი აფიდევიტი/წერილი დონორისგან საჩუქრის ტიპის მითითებით; 3) საბანკო ამონაწერი, სადაც ნაჩვენებია დონაციის საბანკო დეპოზიტი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ ფინანსური ინვესტიციები, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) განაცხადი ინვესტიციის მომწოდებლისგან; 2) საბანკო ამონაწერი, სადაც ნაჩვენებია ინვესტიციის მომწოდებელთან ანგარიშსწორება; 3) სხვა ამონაწერები ან დოკუმენტები, რომლებიც ამტკიცებს საინვესტიციო მოგებას ობლიგაციებიდან, აქციებიდან და ა.შ.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ მემკვიდრეობა, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) უკანასკნელი ნების/ანდერძის ასლი 2) ანდერძის აღმასრულებლის/ადვოკატის/სოლისიტორის/ანდერძის მტკიცებულების ხელმოწერილი წერილი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ იპოთეკა/სესხი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: იპოთეკის/სესხის ხელშეკრულება, სადაც ნაჩვენებია იპოთეკის ან სესხის ღირებულება დაფარვის გეგმით და საბანკო ამონაწერი, სადაც ნაჩვენებია სესხის/იპოთეკის დეპოზიტს თქვენს ანგარიშზე.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ ხელფასი, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. ვერიფიკაციის დასასრულებლად, მოგვაწოდეთ ჩამოთვლილთაგან ერთ-ერთი ან რამდენიმე დოკუმენტი: 1) სახელფასო ამონაწერები, სადაც ნაჩვენებია თქვენი შემოსავალი მინიმუმ ბოლო თვის განმავლობაში; 2) საბანკო ამონაწერი, სადაც ნაჩვენებია ხელფასის ჩარიცხვა დამსაქმებლისგან მინიმუმ ბოლო თვის განმავლობაში; 3) გასული წლის საგადასახადო ამონაწერი.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'ka-GE', 'ქონების წყაროდ მითითებული გაქვთ თვითდასაქმება, თუმცა მოწოდებული დოკუმენტაცია არასაკმარისია და ჩვენს მოთხოვნებს ვერ აკმაყოფილებს. გამოგვიგზავნეთ გასული საგადასახადო წლის საგადასახადო ამონაწერი. დამატებით მომხმარებლებს შეუძლიათ გამოგვიგზავნონ უახლესი ინვოისები/კონტრაქტები/შეთანხმებები თვითდასაქმებული სერვისებისთვის ან მოგება/ზარალის ანგარიშგება, რომელიც ადასტურებს ყოველთვიურ ან წლიურ შემოსავალს', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'ka-GE', 'თქვენ მიერ შევსებულ ქონების დეკლარაციაში აღმოვაჩინეთ შეუსაბამობა. მოწოდებულ დოკუმენტურ მტკიცებულებაში მითითებული აქტივების ჯამური ღირებულება გაცილებით მაღალია და არ შეესაბამება Binance-ზე განთავსებულ ინფორმაციას. მოგვაწოდეთ ზუსტი ინფორმაცია თქვენი კუთვნილი ყველა აქტივის ღირებულების შესახებ და თავიდან გამოგზავნეთ განაცხადი. არასწორი, არასაკმარისი ან შეცდომაში შემყვანი ინფორმაცია თქვენი განაცხადის დროულად დადასტურებას ხელს შეუშლის.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'ka-GE', 'თქვენი დეკლარაციის განხილვისას აღმოვაჩინეთ მნიშვნელოვანი შეცდომები. პროცესის სისწრაფის, თქვენი წლიური შემოსავლის (მთლიანი) მონაცემების სისრულის, აქტივების ჯამური რაოდენობის შესახებ ინფორმაციის და სიმდიდრის წყაროების შესახებ ინფორმაციის სიზუსტის უზრუნველსაყოფად. თქვენს დეკლარაციასთან ერთად წარმოადგინეთ ადეკვატური მტკიცებულება. არასწორი ან არასაკმარისი ინფორმაციის წარდგენა გააჭიანურებს თქვენი განაცხადის განხილვის პროცესს. მადლობას გიხდით თანამშრომლობისთვის.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'ka-GE', 'თქვენ მიერ შევსებულ დასაქმების განაცხადში არასწორი, შეუსაბამო ან არასრული ინფორმაცია აღმოვაჩინეთ. ხელახლა წარადგინეთ თქვენი განაცხადი სწორი ინფორმაციით, მათ შორის: 1) დასაქმების სტატუსი - მიმდინარე დასაქმებული/თვითდასაქმებული/სტუდენტი/პენსიაზე მყოფი/სხვა სტატუსი; 2) დამსაქმებლის/ბიზნესის სახელწოდება - თქვენი დამსაქმებელი კომპანიის/ბიზნესის სახელწოდება; 3) დამსაქმებლის/ბიზნესის მისამართი - დამსაქმებლის/ბიზნესის სარეგისტრაციო მისამართი. დარწმუნდით რომ თქვენ მიერ მოწოდებული ინფორმაცია უახლესია და ემთხვევა დოკუმენტურ მტკიცებულებაში მითითებულ ინფორმაციას.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'ka-GE', 'თქვენი სხვა საბანკო ანგარიშიდან დაფიქსირდა გადარიცხვა. მოგვაწოდეთ ბოლო სამ თვეში გაცემული საბანკო ამონაწერი, სადაც ნაჩვენებია სხვა ანგარიშის გადარიცხვების ისტორია (მინიმუმ ერთთვიანი ვადით).', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'ka-GE', 'თქვენი ფოტოს ხარისხი დაბალია და არ შეესაბამება ჩვენს გარჩევადობის მოთხოვნებს. ხელახლა წარადგინეთ უფრო მაღალი გარჩევადობის მქონე ასლი (სულ მცირე 300 DPI), რომელზეც სრულად ჩანს კადრში მოქცეული ოთხივე კუთხე. ან შეგიძლიათ ვერიფიკაციის გასავლელად სხვა დოკუმენტაცია მოგვაწოდოთ.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
