INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'ka-GE', 'ვერიფიკაცია ვერ მოხერხდა. ამის მიზეზი შეიძლება იყოს უსაფრთხოებასთან დაკავშირებული საკითხები, ან თქვენს ქვეყანაზე/რეგიონზე გავრცელებული აკრძალვა. ბოდიშს გიხდით შექმნილი უხერხულობისთვის.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'ka-GE', 'უკაცრავად, ვერ მოვახერხეთ თქვენი პროფილის ვერიფიკაცია, რადგან თქვენი ასაკი ვერ აკმაყოფილებს მოთხოვნებს. თუ თქვენი დაბადების თარიღი (ასაკი) აკმაყოფილებს მოთხოვნებს, გადაიღეთ მკვეთრი ფოტო და სცადეთ ხელახლა.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
