INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'ka-GE', 'არაკვალიფიციური დოკუმენტები. დოკუმენტის საჭირო ველები არ იკითხება ან არ ჩანს. ატვირთეთ ახალი ფოტო. დარწმუნდით, რომ ფოტო არის ნათელი და მკაფიო და რომ ჩანს დოკუმენტის ოთხივე კუთხე.', '2023-06-18 18:48:30', '2023-06-18 18:48:30') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
