INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'id-ID', 'Verifikasi gagal. Hal ini mungkin disebabkan karena alasan keamanan atau negara/wilayah Anda dibatasi. Mohon maaf atas ketidaknyamanan yang ditimbulkan.', '2023-06-18 18:48:33', '2023-06-18 18:48:33') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'id-ID', 'Maaf, kami tidak dapat memverifikasi profil Anda karena usia Anda tidak sesuai dengan persyaratan. Jika tanggal lahir (usia) Anda memenuhi persyaratan, harap ambil foto dokumen dengan jelas dan coba lagi.', '2023-06-18 18:48:33', '2023-06-18 18:48:33') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
