INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'id-ID', 'Dokumen tidak memenuhi syarat. Bagian dokumen yang diperlukan tidak dapat dibaca atau dilihat. Harap unggah foto baru. Pastikan fotonya cerah dan jelas, serta semua sudut dokumen terlihat.', '2023-06-18 18:48:33', '2023-06-18 18:48:33') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
