INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_DOCUMENT_PAGE_MISSING', 'it-IT', 'Carica una foto del tuo documento aperto alla pagina dei dati anagrafici, con la tua foto e i tuoi dati personali.', '2023-06-18 18:48:34', '2023-06-18 18:48:34') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
