INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'it-IT', 'Documenti non riconosciuti. I campi obbligatori del documento non sono leggibili o visibili. Ti preghiamo di caricare una nuova foto. Assicurati che la foto sia chiara e luminosa e che tutti gli angoli del documento siano visibili.', '2023-06-18 18:48:34', '2023-06-18 18:48:34') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
