INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'it-IT', 'Siamo spiacenti, la regione non è supportata.', '2023-06-18 18:48:34', '2023-06-18 18:48:34') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'ja-JP', '収入の認証 : 給与、自営業、年金、配当、取引、家賃、その他の収入など、バイナンスに申告したすべての収入源について証拠書類を提出してください。申告した収入と一致する十分かつ正確な裏付け書書類を提出してください。情報の誤りや不足があると、申請手続きが遅れます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'ja-JP', '最近の銀行残高証明書 (直近3ヶ月以内に発行されたもの) を提供してください。お客様の名前、発行者名/ロゴ、取引履歴を含み、お客様の雇用主、自営業サービス、年金、手当、配当、取引またはギャンブルの利益、家賃、その他定期的に受け取る入金記録が明確に記載され、バイナンスに申告したお客様のすべての年収を把握できるものである必要があります。これらの書類をデジタルPDFファイルとして送信していただけると幸いです。または物理的な明細書の完全な写真でも結構です。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'ja-JP', 'アップロードされた証拠書類は発行日を明確に示しておらず、受け入れられません。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'ja-JP', '個人情報が表示されない書類をアップロードしました。氏名、発行日、および発行者のロゴがサポート書類に表示されていることを確認してください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'ja-JP', 'お客様の証拠書類 (第三者名義で発行されたもの) は、資金源あるいは資金源の認証書類として受け入れられません。個人名で発行された書類をアップロードするか、第三者の書類を使用してお客様の資金活動や総資産額を確認する方法について明確にしてください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'ja-JP', 'バイナンスユーザーの皆様へ、お客様の申請は承認されました。バイナンスへの投資をお楽しみください!', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'ja-JP', '財務情報または資金源の確認を送信する前に、本人認証プロセスを完了していることを確認してください。プロセスは、[本人認証] タブに移動し、地域の要件に応じて有効なパスポートまたはその他の受け入れ可能な本人認証書類をアップロードすることで完了することができます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'ja-JP', '親愛なるユーザーの皆様、バイナンスはすべてのユーザーアカウントに1日あたり200万ドルの新しい法定通貨の制限を提供しました。したがって、現在の制限引き上げリクエスト(500k/1ミル/2ミル USD) は不要と見なされます。取引をお楽しみください!', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'ja-JP', '残念ながら、提供された証拠で申請を確認することはできませんでした。追加の支援のために、コンプライアンス部門とのチャットに招待します。数分後に招待メールが届きます。「今すぐチャット」ボタンをクリックして続行してください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'ja-JP', 'アップロードされた証拠書類は十分に明確ではなく、当社の認識要求を満たしていません。書類の原本をアップロードしてください。これらの書類をデジタルPDFファイルとして送信していただけると幸いです。または、書類の四隅がすべて見える物理的な明細書の全面写真でも結構です。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'ja-JP', 'PEP宣誓フォームに正確に回答を入力してください。お客様がPEPに分類されるかどうか、氏名、役職、関係 (所属するPEPである場合)、およびPEPであった期間などをお知らせください。この情報を提供後、申請書を再提出することができます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'ja-JP', '財務情報または資金源の確認を送信する前に、住所の証明の確認プロセスを完了していることを確認してください。このプロセスを完了するには、[本人認証] タブに移動し、過去3ヶ月間に発行された有効な銀行取引明細書/公共料金の請求書/税務書類を、あなたの名前で、正確な住所が表示されている状態でアップロードします。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'ja-JP', '主な資金源として手当を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 過去3ヶ月間の手当の振込を示す銀行取引明細書; 2) 政府発行の手当またはその他の社会保障の明細書。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'ja-JP', 'あなたは、資金源が資産の売却からのものであると宣言しました。資産売却により銀行口座に入金されたことを示す銀行明細書 (お客様の氏名が明記され、発行日が申込日から3ヶ月以内のもの) を提出してください。これらのをデジタルPDFファイルとして送信していただけると幸いです。または物理的な明細書の全面写真でも結構です。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'ja-JP', 'お客様のアカウント資金が仮想通貨マイニング活動から発生したものであることを宣言しています。お客様の申請手続きを進めるために、次のいずれかを提供してください: 1) マイニングに使用されるハードウェアの購入証明 (お客様と販売者の両方の詳細を示すもの); 2) 関連するプラットフォーム/取引所からのすべてのマイニング収益の証明書;いずれの場合も、マイニングされたすべてコインのアクティビティの詳細とウォレットアドレスとトランザクションIDを表示している、少なくとも3ケ月のトランザクション履歴のスクリーンショットが必要です。これらには、関連するプラットフォーム/取引所から取得し、アカウントの詳細を含める必要があります。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'ja-JP', '主な資金源としてデイトレードを選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 先月の取引活動を証明する取引明細書と、出金された利益が銀行口座に入金されたことを示す銀行取引明細書。両方の書類に口座登録の詳細と発行者のロゴが記載されている必要があります; 2) 取引利益からの収入を証明する前年度の納税証明書。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'ja-JP', '主な資金源として配当金の支払い/会社からの利益を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 配当計算書; 2) ディストリビューション契約; 3)配当金の支払いを示す銀行取引明細書; 4) 監査された会社の最新決算報告書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'ja-JP', '主な資金源として寄付を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 不動産またはその他の資産の寄付契約書; 2) 寄付者の署名入り宣誓書/手紙; 3) 寄付の入金を示す銀行取引明細書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'ja-JP', '主な資金源としてギャンブルを選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 先月のギャンブル活動を証明する取引明細書と、出金された利益が銀行口座に入金されたことを示す銀行取引明細書。両方の書類にアカウント登録の詳細と発行者のロゴが記載されている必要があります; 2) ギャンブルの利益からの収入を証明する前年度の納税証明書。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'ja-JP', '主な資金源として遺産相続を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上をお送りください: 1) 遺言/遺言書の写し、2) 遺言執行者 (弁護士/法務官/遺言検認者) からの署名入りの手紙', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'ja-JP', '主な資金源としてローン/住宅ローンを選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、以下を送信してください: ローン金額と返済計画を示すローン/住宅ローン契約書、およびお客様の口座にローン/住宅ローンの入金されたことを示す銀行取引明細書。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'ja-JP', '主な資金源としてパッシブインカムを選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上をお送りください: 1) 署名された賃貸/リース契約と次のいずれか: a. 最新のレンタル/リース決済の支払いを示す銀行取引明細書; b. 最新の賃貸/リース領収書; 2)パッシブインカムを証明する先月発行されたその他の書類 (例:本の印税、アフィリエイトマーケティング、ステーキングなど);', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'ja-JP', '主な資金源として年金を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 過去3ヶ月間の年金振込を示す銀行取引明細書; 2) 政府発行の年金明細書; 3) 年金基金の明細書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'ja-JP', '主な資金源として給与を選択しましたが、提供された証拠書類では不十分であり、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 少なくとも先月からの収入を示す給与明細; 2) 少なくとも先月の雇用主からの給与支払いを示す銀行取引明細書; 3) 前年度の納税証明書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'ja-JP', '主な資金源として金融資産の売却を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 投資プロバイダーの取引明細書; 2) 投資プロバイダーからの決済を示す銀行取引明細書; 3)債券、株式などからの投資利益を証明するその他の取引明細書または書類;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'ja-JP', '主な資金源として不動産やその他の資産の売却を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上をお送りください: 1) 売買契約/決済明細書; 2) 不動産売却を認証する弁護士/弁護士/不動産業者からの署名入りの手紙; 3) 土地登記所/権利証書の写し;さらに、お客様の銀行口座への売却によって得た資金の入金が記載された銀行取引明細書をお送りいただくことも可能です。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'ja-JP', '主な資金源として貯金を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。預金口座 (過去3ヶ月以内に発行されたもの) の明細書をお送りください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'ja-JP', '主な資金源として自営業を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。前年度の納税証明書をお送りください。さらに、自営業のサービスに関する最近の請求書/契約書/合意書、または損益計算書を送信することで、月収または年収を証明することができます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'ja-JP', '主な資金源として会社の利益 (株式/配当) を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 配当計算書; 2) ディストリビューション契約; 3) 配当金の支払いを示す銀行取引明細書; 4) 監査された会社の最新決算報告書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'ja-JP', '仮想通貨投資の認証: 仮想通貨が財産の源泉であるとして、提供された証拠は不十分です。他の取引所からの明細書、コールドウォレットのスクリーンショット、仮想通貨購入領収書、その他の関連書類を提出してください。これらの追加情報をもとに、認証審査を再開します。提供される証拠は、お客様の宣誓内容と一致していることを確認してください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'ja-JP', '主な資金源として寄付を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 不動産またはその他の資産の寄付契約書; 2) 寄付者の署名入り宣誓書/手紙; 3) 寄付の入金を示す銀行取引明細書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'ja-JP', '主な資金源として金融投資を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 投資プロバイダーの取引明細書; 2) 投資プロバイダーからの決済を示す銀行取引明細書; 3) 債券、株式などからの投資利益を証明するその他の取引明細書または書類;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'ja-JP', '主な資金源として遺産相続を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上をお送りください: 1) 遺言/遺言書の写し; 2) 遺言執行者 (弁護士/弁護士/遺言検認者) からの署名入りの手紙;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'ja-JP', '主な財務情報として住宅ローン/ローンを選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、住宅ローンまたはローンの価値と返済計画を示す住宅ローン/ローン契約、およびアカウントへのローン/住宅ローンの預金を示す銀行取引明細書を送信してください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'ja-JP', '主な資金源として給与を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。認証を完了するには、次の1つ以上を送信してください: 1) 少なくとも先月からの収入を示す給与明細; 2) 少なくとも先月の雇用主からの給与支払いを示す銀行取引明細書; 3) 前年度の納税証明書;', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'ja-JP', '主な資金源として自営業を選択しましたが、提供された証拠書類は十分ではなく、要件を満たしていません。前年度の納税証明書をお送りください。さらに、自営業のサービスに関する最近の請求書/契約書/合意書、または損益計算書を送信することで、月収または年収を証明することができます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'ja-JP', '総合財産申告書に不一致があることを特定しました。提供された証拠書類は、総資産の価値が著しく高いことを示しており、お客様がバイナンスで申告したものと一致しません。所有するすべての資産の全体 (概算) 合計額を正確に記入の上、申請書を再度送信してください。不正確な情報、不十分な情報、または誤解を招くような情報を提供することは、迅速な申請承認の妨げになります。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'ja-JP', 'お客様の申請内容を確認したところ、重大な誤りがあることが判明しました。迅速に手続きを進めるために、年収 (税込み)、総資産、財産の源泉について、正確かつ完全な情報を提供してください。お客様の宣誓とともに、十分な証拠資料を提出してください。情報の誤りや不足があると、申請手続きが遅れます。ご協力ありがとうございます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'ja-JP', '雇用詳細に関する申告で記載の誤り、不一致、または不備があることが判明しました。以下を含む正確な情報を添えて申請書を再提出してください: 1) 雇用状況 - 現在の雇用者/自営業/学生/退職/その他の地位; 2) 雇用主/会社名 - 雇用主の会社名/企業名; 3) 雇用主/会社の住所 - 登録された雇用主/会社の住所;提供される情報が最新であること、および証拠書類で提供される情報と一致することを確認してください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'ja-JP', '他の銀行口座からの送金に気付きました。過去3ヶ月間に発行された、他のアカウントの取引履歴 (少なくとも1ヶ月の取引をカバー) を示す銀行取引明細書をお送りください。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'ja-JP', '写真の画質が鮮明ではなく、当社の視認要件を満たしていません。より高い解像度 (少なくとも300DPI) で全ページの書類の四隅がすべて見えるコピーを再送信してください。または、確認を完了するために別の書類を提供することもできます。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
