INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'ja-JP', '申し訳ございませんが、この地域には対応していません。', '2023-06-18 18:48:35', '2023-06-18 18:48:35') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'kk-KZ', 'Табысты растау: Binance биржасында жарияланған барлық табыс көздеріне, соның ішінде жалақы, өзін-өзі жұмыспен қамту, зейнетақы, дивидендтер, сауда, жалдау немесе басқа кіріс үшін құжаттық дәлелдерді қамтамасыз етіңіз. Декларацияланған кірісіңізге сәйкес келетін жеткілікті және дәл растайтын құжаттарды жіберіңіз. Қате немесе жеткіліксіз ақпарат бекітуді кешіктіреді.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'kk-KZ', 'Соңғы банк мәлімдемесін (соңғы 3 айда берілген) ұсыныңыз. Онда аты-жөніңіз, эмитент атауы/логотипі және жұмыс берушіден ай сайынғы аударымдарды, өзін-өзі жұмыспен қамтыған қызметтерді, зейнетақыны, жәрдемақыларды, дивидендтерді, сауда немесе ойын бизнесінен пайда алуды, жалдау ақысын немесе тұрақты негізде алынған Binance жүйесінде жарияланған толық жылдық кірісіңізді көрсететін кез келген басқа аударымдарды нақты көрсететін транзакция тарихы қамтылуы керек. Біз бұл құжаттарды сандық .pdf пішімінде алғанды немесе мәлімдемелердің толық фотосуреттерін алғанды жөн көреміз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'kk-KZ', 'Жүктеп салынған құжаттық дәлелде құжаттың нақты шығарылу күні жоқ және оны қабылдауға болмайды.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'kk-KZ', 'Жеке мәліметтеріңіз көрінбейтін құжаттарды жүктеп салдыңыз. Толық аты-жөніңіз, құжаттың шығарылған күні және кез келген эмитент логотиптері ілеспе құжаттамада көрсетілгеніне көз жеткізіңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'kk-KZ', 'Сіздің құжаттық дәлелдеріңіз (үшінші тұлғалардың аты-жөнімен берілген) сіздің байлық көзіңізді немесе қаражат көзіңізді растайтын құжат ретінде қабылданбайды. Жеке атыңызбен берілген құжаттарды жүктеп салыңыз немесе үшінші тарап құжаттарын сіздің фиат әрекетіңізді немесе активтің жалпы құнын тексеру үшін қалай пайдалануға болатынын түсіндіріңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'kk-KZ', 'Құрметті Binance пайдаланушысы, сіздің өтініміңіз мақұлданды! Binance арқылы инвестициялаңыз!', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'kk-KZ', 'Байлық немесе қаражат көзі туралы куәлікті жібермес бұрын, жеке басты растау процесін аяқтаңыз. Жергілікті талаптарға байланысты жеке куәлікті растау қойындысына өтіп, жарамды төлқұжатты немесе кез келген басқа қолайлы сәйкестендіру құжатын жүктеп салу арқылы процесті аяқтауға болады.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'kk-KZ', 'Құрметті пайдаланушы, Binance жүйесі біздің барлық пайдаланушы шоттарымыз үшін күніне 2 миллион АҚШ доллары көлеміндегі жаңа фиат шектеулерін ұсынды. Сондықтан ағымдағы шектеуді арттыру сұрауыңыз (500 мың/1 миллион/2 миллион АҚШ долларына) өзекті емес деп есептеледі. Сауда жасаңыз!', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'kk-KZ', 'Өкінішке орай, сіздің өтінішіңізді ұсынылған дәлелдермен тексеру мүмкін болмады. Сізге қосымша көмек көрсету үшін, сізді біздің сәйкестік департаментімізбен чат арқылы сөйлесуге шақырамыз. Бірнеше минутта сізге шақыру электрондық хабары келеді. Жалғастыру үшін, «Қазір байланысу» түймесін басыңыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'kk-KZ', 'Жүктелген құжаттық дәлелдер жеткілікті деңгейде анық емес және біздің анықтық талаптарымызға сәйкес келмейді. Түпнұсқа құжатты жүктеп салыңыз. Біз бұл құжаттарды сандық .pdf пішімінде алғанды немесе құжаттың барлық төрт бұрышы көрінетін мәлімдемелердің толық фотосуреттері ретінде алғанды жөн көреміз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'kk-KZ', 'PEP декларациясының үлгісін нақты жауаптармен толтырыңыз. Бізге сіздің саясатқа қатысты адам санатына жататындығыңызды, толық аты-жөніңізді, лауазымыңызды, қарым-қатынасыңызды (егер сіз қауымдастық бойынша саясатқа қатысты адам болсаңыз) және қанша уақыт саясатта болғаныңызды хабарлаңыз. Осы ақпаратты бергеннен кейін, өтініміңізді қайта жіберуіңізге болады.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'kk-KZ', 'Байлық немесе қаражат көзі туралы куәлікті жібермес бұрын, Мекенжай растамасын тексеру процесін аяқтаңыз. Бұл процесті жеке басты растау қойындысына өтіп, сіздің атыңызға және нақты көрінетін мекенжайы көрсетілген соңғы үш айда берілген жарамды банк мәлімдемесін/коммуналдық төлемді/салық құжатын жүктеп салу арқылы аяқтай аласыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Жәрдемақыны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Соңғы 3 айдағы жәрдемақы аударымдарын көрсететін банк мәлімдемесі; 2) Мемлекет берген жәрдемақы немесе басқа да әлеуметтік төлемдер туралы анықтама.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'kk-KZ', 'Сіз өзіңіздің қаражат көзіңіз активтер саудасынан пайда болатынын жарияладыңыз. Өтініш берген күннен бастап 3 ай ішінде сіздің аты-жөніңізді және берілген күніңізді нақты көрсете отырып, активтеріңізді сатудан банк шотыңызға түскен төлемді көрсететін банк мәлімдемесін беріңіз. Біз бұл құжаттарды сандық .pdf пішімінде алғанды немесе мәлімдемелердің толық фотосуреттерін алғанды жөн көреміз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'kk-KZ', 'Өз шотыңыздағы қаражаттың криптовалюта өндіру әрекеттерінен алынғанын мәлімдедіңіз. Өтініміңізді қолдау үшін мынаны көрсетіңіз: 1) Майнинг үшін пайдаланылатын жабдықты сатып алу растамасы (өз мәліметтеріңізді және сатушы мәліметтерін көрсету); 2) Тиісті платформадан/биржадан алынған барлық майнинг кірістерін растау. Әрбір жағдайда бізге майнинг монеталарымен жасалған барлық әрекеттердің егжей-тегжейлі сипаттамасы және әмиян мекенжайлары мен транзакция идентификаторлары көрсетілген кемінде 3 айлық транзакциялар тарихының скриншоттары қажет. Олар тиісті платформадан/биржадан алынуы және шот деректерін қамтуы керек.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Күндізгі сауданы таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Сіздің соңғы айдағы сауда әрекетіңізді растайтын транзакция есептері, ЖӘНЕ шотыңыздан пайданың алынуын көрсететін банк мәлімдемесі. Екі құжатта да шотты тіркеу мәліметтері және эмитенттің логотипі болуы керек; 2) Саудадан түскен табысыңызды көрсететін алдыңғы салық жылының салық декларациясы.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Дивиденд төлемдерін/Компаниядан алынатын табысты таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Дивиденд мәлімдемелері; 2) Тарату келісімдері; 3) Дивиденд төлемдерін көрсететін банк мәлімдемесі; 4) Компания шоттарының ең соңғы аудиті.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Қайырымдылықты таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Жылжымайтын мүлікті немесе басқа да активтерді сыйға беру келісімі; 2) Сыйлықтың сипатын жариялайтын сыйға тартушының қолы қойылған аффидавит/хат; 3) Қайырымдылықтың банк депозитін көрсететін банк мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Құмар ойынды таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Сіздің соңғы айдағы құмар ойын бойынша әрекеттеріңізді растайтын транзакция есептері, ЖӘНЕ шотыңыздан пайданың алынуын көрсететін банк мәлімдемесі. Екі құжатта да шотты тіркеу мәліметтері және эмитенттің логотипі болуы керек; 2) Құмар ойыннан түскен табысыңызды көрсететін алдыңғы салық жылының салық декларациясы.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'kk-KZ', 'Сіз негізгі Қаражат көзі ретінде Мұраны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Өсиет/Өсиет көшірмесі; 2) Өсиет атқарушысының қолы қойылған хат (адвокат/заңгер/өсиеттің куәландырылған көшірмесін алған адам).', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Несиелерді/Ипотеканы таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін мыналарды жіберіңіз: Несие сомасы мен өтеу жоспарын көрсететін несие/ипотека келісімшарты ЖӘНЕ шотыңыздағы несие/ипотека салымдарын көрсететін банк мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Пассивті табысты таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Қол қойылған жалдау/лизинг шарты ЖӘНЕ төмендегілердің бірі: a. Соңғы жалдау/лизинг төлемі көрсетілген банктің үзінді көшірмесі; b. Ең соңғы жалдау/жалға беру түбіртектері; 2) Сіздің пассивті кірісіңізді растайтын соңғы айдағы кез келген басқа құжаттар (мысалы, кітаптарға арналған автор қаламақысы, серіктестік маркетингі, стейкинг және т.б.).', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Зейнетақыны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Соңғы 3 айдағы зейнетақы аударымдарын көрсететін банк мәлімдемесі; 2) Мемлекет берген зейнетақы туралы анықтама; 3) Зейнетақы қорының мәлімдемелері.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Жалақыны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Кем дегенде соңғы айдағы табысыңызды көрсететін төлем түбіртектері; 2) Жұмыс берушіден алынатын кем дегенде соңғы айдағы жалақы төлемдерін көрсететін банк мәлімдемесі; 3) Алдыңғы есептік жылдағы салық мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Қаржылық активтер саудасын таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Инвестициялық провайдеріңізден алынған мәлімдеме; 2) Инвестициялық провайдеріңіздің есеп айырысуын көрсететін банк мәлімдемесі; 3) Облигациялардан, акциялардан түскен және т.б. инвестициялық пайданы растайтын басқа мәлімдемелер немесе құжаттар.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Жылжымайтын мүлік немесе басқа саудасын таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Сауда келісімшарты/есеп айырысу актісі; 2) Мүлікті сатуды растайтын адвокаттың/заңгердің/жылжымайтын мүлік агентінің қол қойылған хаты; 3) Жер кадастрының/құқықтық актінің көшірмелері. Банктік шотыңызға қаражаттың депозит ретінде салынғанын көрсететін банк мәлімдемесінің көшірмесін жібере аласыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Жинақты таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Бізге жинақ шоты мәлімдемесінің көшірмесін (соңғы 3 айда берілген) жіберуіңізді сұраймыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'kk-KZ', 'Сіз негізгі қаражат көзі ретінде Өзін-өзі жұмыспен қамтуды таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Өткен есептік жылдағы салық мәлімдемесін жіберіңіз. Сонымен қатар сіз өзін-өзі жұмыспен қамтушылардың қызметтері үшін соңғы шот-фактураларды/келісімшарттарды/келісімдерді немесе айлық немесе жылдық кірісті растайтын пайда/шығын туралы есептерді жібере аласыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'kk-KZ', 'Сіз байлық көзі ретінде Компания пайдасын (акциялар/дивидендтер) таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Дивиденд мәлімдемелері; 2) Тарату келісімдері; 3) Дивиденд төлемдерін көрсететін банк мәлімдемесі; 4) Компания шоттарының ең соңғы аудиті.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'kk-KZ', 'Крипто инвестицияңызды растаңыз: негізгі байлық көзі ретінде криптовалюта үшін берген дәлелдеріңіз жеткіліксіз. Басқа биржалардың мәлімдемелерін, суық әмияндардың скриншоттарын, крипто сатып алу түбіртектерін немесе кез келген қатысты құжаттарды жіберу арқылы қосымша растауды қамтамасыз етіңіз. Ұсынылған дәлелдердің жүйедегі декларацияңызға сәйкес келетініне көз жеткізіңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Қайырымдылықтарды таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Жылжымайтын мүлікті немесе басқа да активтерді сыйға беру келісімі; 2) Сыйлықтың сипатын жариялайтын сыйға тартушының қолы қойылған аффидавит/хат; 3) Қайырымдылықтың банк депозитін көрсететін банк мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Қаржылық инвестицияны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Инвестициялық провайдеріңізден алынған мәлімдеме; 2) Инвестициялық провайдеріңіздің есеп айырысуын көрсететін банк мәлімдемесі; 3) Облигациялардан, акциялардан түскен және т.б. инвестициялық пайданы растайтын басқа мәлімдемелер немесе құжаттар.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Мұраны таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Өсиет/Өсиет көшірмесі; 2) Өсиет атқарушысының қолы қойылған хат (адвокат/заңгер/пробата).', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Ипотеканы/Несиені таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Растауды аяқтау үшін мыналарды жіберіңіз: ипотека немесе несие мөлшері мен өтеу жоспарын көрсететін ипотека/несие келісімшарты ЖӘНЕ шотыңыздағы несие/ипотека салымын көрсететін банк мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Айлықты таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Қарап шығуды аяқтау үшін бізге төмендегілердің біреуін немесе бірнешеуін жіберіңіз: 1) Кем дегенде соңғы айдағы табысыңызды көрсететін төлем түбіртектері; 2) Жұмыс берушіден алынатын кем дегенде соңғы айдағы жалақы төлемдерін көрсететін банк мәлімдемесі; 3) Алдыңғы есептік жылдағы салық мәлімдемесі.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'kk-KZ', 'Сіз негізгі байлық көзі ретінде Өзін-өзі жұмыспен қамтуды таңдадыңыз, бірақ ұсынылған құжаттар жеткіліксіз және талаптарымызға сай емес. Өткен есептік жылдағы салық мәлімдемесін жіберіңіз. Сонымен қатар сіз өзін-өзі жұмыспен қамтушылардың қызметтері үшін соңғы шот-фактураларды/келісімшарттарды/келісімдерді немесе айлық немесе жылдық кірісті растайтын пайда/шығын туралы есептерді жібере аласыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'kk-KZ', 'Сіздің жалпы байлық декларацияңызда сәйкессіздік анықталды. Ұсынылған құжаттамалық дәлелдер активтің жалпы құнының айтарлықтай жоғары екенін көрсетеді және Binance жүйесіне жариялаған мәліметке сәйкес келмейді. Сізге тиесілі және қайта өтініш берген барлық активтердің жалпы (шамамен) жалпы құны туралы нақты ақпаратты бізге беріңіз. Қате, жеткіліксіз немесе жаңылыстыратын ақпаратты ұсыну өтінішіңізді тезірек мақұлдауға жол бермейді.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'kk-KZ', 'Декларацияңызды қарап шыққаннан кейін біз елеулі қателерді таптық. Жылдам процесті қамтамасыз ету үшін жылдық табысыңыз (жалпы), жалпы активтеріңіз және байлық көздері туралы дәл және толық деректерді қамтамасыз етіңіз. Декларациямен бірге тиісті дәлелдерді жіберіңіз. Қате немесе жеткіліксіз ақпарат өтінішіңізді кешіктіреді. Серіктестік білдіргеніңізге рақмет.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'kk-KZ', 'Біз сіздің еңбек туралы декларацияңыздан дұрыс емес, сәйкес келмейтін немесе толық емес ақпаратты таптық. Нақты ақпаратпен қайта өтініш беріңіз, соның ішінде: 1) Жұмыспен қамтылу мәртебесі – ағымдағы Жұмысшы/Өзін-өзі жұмыспен қамтушы/Студент/Зейнеткер/Басқа мәртебе; 2) Жұмыс беруші/Кәсіпорын атауы – Жұмыс беруші компанияңыздың атауы/кәсіпорын атауы; 3) Жұмыс беруші/Кәсіпорын мекенжайы – тіркелген Жұмыс беруші/Бизнес мекенжайы. Ұсынылған ақпараттың жаңартылғанына және құжаттық дәлеліңізде көрсетілген ақпаратқа сәйкес келетініне көз жеткізіңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'kk-KZ', 'Сіздің басқа банк шотыңыздан қаражат аударылғанын байқадық. Бізге басқа шоттың транзакция тарихын көрсететін соңғы 3 айдағы банк мәлімдемесін жіберіңіз (кемінде 1 айлық транзакцияларды қамтиды).', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'kk-KZ', 'Фотосуретіңіз анық емес және біздің көріну талаптарына сәйкес келмейді. Бүкіл бетті кадрға төрт бұрышпен көрсететін ажыратымдылығы жоғары (кемінде 300 dpi) көшірмені қайта жіберіңіз. Не болмаса растауды аяқтау үшін басқа құжаттарды ұсынуыңызға болады.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
