INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'kk-KZ', 'Растау орындалмады. Бұл қауіпсіздік себептеріне байланысты болуы немесе сіздің еліңізде/аймағыңызда тыйым салынған болуы мүмкін. Орын алған қолайсыздықтар үшін кешірім сұраймыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'kk-KZ', 'Өкінішке орай, жасыңыз талаптарға сәйкес келмейтіндіктен, профиліңіз расталмады. Туған күніңіз (жасыңыз) талапқа сай болса, суретті анық түсіріп, әрекетті қайталаңыз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
