INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ID_INVALID', 'kk-KZ', 'Кешіріңіз, сіздің жеке куәлігіңіз жарамсыз және оны растау үшін пайдалану мүмкін емес. Жеке басты куәландыратын басқа құжатты қолданып көріңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
