INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNFILLED_ID', 'kk-KZ', 'Жүктеп салынған құжат қолтаңбалар мен мөрлерді қамтымайды.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'kk-KZ', 'Талаптарға сәйкес келмейтін құжаттар. Құжаттың міндетті өрістерін оқу мүмкін емес немесе олар көрінбейді. Жаңа фотосурет жүктеп салыңыз. Фотосуреттің ашық және анық екеніне және құжаттың барлық бұрыштары көрінетініне көз жеткізіңіз.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_ADDRESS', 'kk-KZ', 'Құжаттардың мекенжайы пайдаланушы енгізген мекенжайға сәйкес келмейді.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'kk-KZ', 'Кешіріңіз, бұл аймаққа қолдау көрсетілмейді.', '2023-06-18 18:48:36', '2023-06-18 18:48:36') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'lv-LV', 'Ienākumu verifikācija: iesniedz pierādījuma dokumentus par visiem platformā Binance deklarētajiem ienākumu avotiem, tostarp par darba algu, pašnodarbinātās personas ienākumiem, pensiju, dividendēm, tirdzniecību, nomu un citiem ienākumiem. Iesniedz pietiekamus un precīzus pamatojuma dokumentus, kas atbilst deklarētajiem ienākumiem. Nepareizas vai nepietiekamas informācijas gadījumā iesnieguma apstiprināšana var ieilgt.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'lv-LV', 'Lūdzu, iesniedz pēdējos 3 mēnešos izdotu bankas konta izrakstu. Tajā ir jābūt redzamam tavam vārdam, uzvārdam, izdevēja nosaukumam/logotipam, darījuma vēsturei, kurā ir skaidri redzami ikmēneša pārskaitījumi no tava darba devēja, pašnodarbinātā pakalpojumu saņēmējiem, pensijas maksājumi, pabalstu, dividenžu, tirdzniecības vai azartspēļu peļņas maksājumi vai citi regulāri maksājumi, kas atbilst Binance platformā norādītajiem ieņēmumiem gadā. Šie dokumenti ir jāiesniedz .pdf formātā vai arī jāuzņem to fotoattēli pilnā izmērā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'lv-LV', 'Augšupielādētajos dokumentos nav skaidri redzams izdošanas datums, tāpēc tos nevar pieņemt.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'lv-LV', 'Tu augšupielādēji dokumentus, kuros nav skaidri redzami personas dati. Lūdzu, pārliecinies par to, ka iesniegtajos dokumentos ir skaidri redzams to izdošanas datums un izdevēja logotipi.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'lv-LV', 'Tavus dokumentus (ar trešo pušu vārdiem, uzvārdiem) nav iespējams pieņemt kā līdzekļu izcelsmes verifikācijas dokumentus. Augšupielādē dokumentus, kas ir izdoti uz tava vārda, uzvārda vai sniedz skaidrojumu par to, kāpēc vēlies izmantot trešo pušu dokumentus, lai verificētu tavas darbības ar bezseguma valūtām vai kopējo aktīvu vērtību.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'lv-LV', 'Cienītais Binance lietotāj, tavs pieteikums tika apstiprināts. Izbaudi ieguldīšanu ar Binance!', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'lv-LV', 'Pirms nosūtīt dokumentus līdzekļu izcelsmes vai ienākumu verifikācijai, lūdzu, pārliecinies par to, ka kontā ir veikts identitātes verifikācijas process. Tu vari veikt šo procesu identitātes verifikācijas cilnē augšupielādējot derīgas pases vai cita personu apliecinoša dokumenta kopiju atbilstoši reģionālajām prasībām.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'lv-LV', 'Cienītais lietotāj, Binance ieviesa jaunu dienas bezseguma valūtas ierobežojumu 2 miljonu ASV dolāru apmērā visiem mūsu lietotāju kontiem. Tāpēc tavs pašreizējais pieprasījums palielināt limitu (līdz 500 000, 1 milj., 2 milj. ASV dolāru) tiek uzskatīts par nevajadzīgu. Izbaudi tirdzniecību!', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'lv-LV', 'Diemžēl mēs nevarējām veikt tava pieteikuma verifikāciju, izmantojot iesniegto informāciju. Lai palīdzētu tev, lūdzam pievienoties tērzēšānai ar mūsu atbilstības nodaļu. Pēc dažām minūtēm saņemsi uzaicinājumu e-pastā. Lūdzu, noklikšķini uz pogas "Tērzēt", lai turpinātu.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'lv-LV', 'Augšupielādēti dokumenti nav pietiekami skaidri vai neatbilst mūsu redzamības prasībām. Lūdzu, augšupielādē oriģinālā dokumenta fotoattēlu. Šie dokumenti ir jāiesniedz .pdf formātā vai pilna izmēra fotoattēlus, kuros redzami visi dokumenta stūri.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'lv-LV', 'Lūdzu, aizpildi mūsu PNP deklarācijas veidlapu, norādot precīzas atbildes. Lūdzu, informē mūs par to, vai tu esi politiski nozīmīga persona, kā arī norādi savu vārdu,uzvārdu, saistību (ja ir saistība ar PNP) un laiku, cik ilgi tu esi PNP. Pēc šīs informācijas norādīšanas vari iesniegt pieteikumu atkārtoti.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'lv-LV', 'Pirms nosūti dokumentus līdzekļu izcelsmes vai ienākumu verifikācijai, lūdzu, pārliecinies par to, ka kontā ir veikts adreses verifikācijas process. Tu vari veikt šo procesu identitātes verifikācijas cilnē augšupielādējot derīgu bankas konta izrakstu/rēķinu par komunālajiem pakalpojumiem/nodokļu dokumentu, kas ir pēdējo trīs mēnešu laikā izdots tavā vārdā un kurā ir redzama adrese.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'lv-LV', 'Tu norādīji pabalstu kā savu līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādītos dokumentus, lai pabeigtu verifikāciju: 1) bankas konta izraksts, kurā ir redzami pabalsta pārskaitījumi pēdējo 3 mēnešu laikā; 2) valsts izdotu paziņojumu par pabalsta piešķiršanu vai citu sociālo pabalstu apliecinājumu.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'lv-LV', 'Tu norādīji, ka tavu līdzekļu izcelsme ir aktīvu pārdošana. Lūdzu, iesniedz bankas konta izrakstu, kurā redzama maksājuma par tavu aktīvu pārdošanu saņemšana, kā arī skaidri redzams tavs vārds, datums un izdošanas datums, kas nav vēlāk par 3 mēnešiem kopš pieteikuma iesniegšanas. Šie dokumenti ir jāiesniedz .pdf formātā vai arī jāuzņem to fotoattēli pilnā izmērā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'lv-LV', 'Tu norādīji, ka līdzekļi tavā kontā ir iegūti kriptovalūtu ieguves rezultātā. Lai apstiprinātu tavu pieteikumu, lūdzu, iesniedz: 1) aparatūras, kas tiek izmantota kriptovalūtu ieguvei, iegādes apliecinājumu (jābūt redzamai tavai un pārdevēja informācijai); 2) visas ieguves ieņēmumu no attiecīgās platformas/biržas apliecinājums. Katrā gadījumā mēs pieprasām ekrānuzņēmumus, kuros redzama darījumu vēsture vismaz par 3 mēnešiem ar informāciju par iegūtajām kriptovalūtām, maku adresēm un darījumu ID. Ekrānuzņēmumiem ir jābūt uzņemtiem atbilstošā platformā/biržā un tajos ir jābūt redzamai tava konta informācijai.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'lv-LV', 'Tu norādīji tirdzniecību biržā kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) darījumu izraksti, kas apliecina tavas tirdzniecības darbības par pēdējo mēnesi UN bankas konta izrakstu, kurā ir redzama peļņas izmaksa uz tavu bankas kontu. Abos dokumentos ir jābūt redzamai konta reģistrācijas informācijai un izdevēja logotipam; 2) nodokļu deklarācija par iepriekšējo nodokļu gadu, kas apliecina, ka tu guvi peļņu no tirdzniecības.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'lv-LV', 'Tu norādīji dividenžu maksājumu/uzņēmuma peļņu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums vienu vai vairākus tālāk norādītos dokumentus verifikācijas veikšanai: 1) dividenžu maksājumu izraksti; 2) līgumi par peļņas sadalījumu; 3) bankas konta izraksts, kurā ir redzami dividenžu maksājumi; 4) jaunākais veiktais uzņēmuma kontu audits.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'lv-LV', 'Tu norādīji ziedojumus kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) līgums par nekustamā īpašuma vai citu aktīvu ziedošanu; 2) donora parakstīts apliecinājums/vēstule, kurā norādīta dāvana; 3) bankas konta izraksts, kurā redzama ziedojuma iemaksa kontā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'lv-LV', 'Tu norādīji azartspēles kā savu līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) darījumu izraksti, kas apliecina tavas tirdzniecības darbības par pēdējo mēnesi UN bankas konta izrakstu, kurā ir redzama peļņas izmaksa uz tavu bankas kontu. Abos dokumentos ir jābūt redzamai konta reģistrācijas informācijai un izdevēja logotipam; 2) nodokļu deklarācija par iepriekšējo nodokļu gadu, kas apliecina, ka tu guvi peļņu no azartspēlēm.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'lv-LV', 'Tu norādīji mantojumu kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) novēlējuma/testamenta kopiju; 2) testamenta izpildītāja (jurista, juriskonsulta, mantojuma apliecinājuma izsniedzēja u.tml.) parakstītu vēstuli.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'lv-LV', 'Tu norādīji aizdevumus/hipotēkas kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti tālāk norādīto, lai pabeigtu tavu verifikāciju: aizdevuma/hipotēkas līgums, kurā ir redzama aizdevuma summa un atmaksas plāns, UN bankas konta izraksts, kurā ir redzama aizdevuma/hipotēkas iemaksa tavā kontā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'lv-LV', 'Tu norādīji pasīvos ienākumus kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti tālāk norādīto, lai pabeigtu verifikāciju: 1) parakstīts nomas/īres līgums UN viens no tālāk norādītā: a. Bankas konta izraksts, kurā redzams pēdējais nomas/īres maksājums; b. Jaunākās nomas/īres kvītis; 2) jebkuri citi tavus pasīvos ienākumus apliecinoši dokumenti (piem., autoratlīdzības maksājumi par grāmatu, mārketinga ieņēmumi, steikings utt.) par pēdējo mēnesi.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'lv-LV', 'Tu norādīji pensiju kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādītos dokumentus, lai pabeigtu verifikāciju: 1) bankas konta izraksts, kurā ir redzami pensijas pārskaitījumi pēdējo 3 mēnešu laikā; 2) valsts izdotu paziņojumu par pensijas piešķiršanu; 3) pensiju fonda pārskatus.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'lv-LV', 'Tu norādīji algu kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Atsūti mums vienu no tālāk norādītajiem dokumentiem verifikācijas veikšanai: 1) algas maksājumu izraksti, kuros ir redzami tavi ieņēmumi vismaz par iepriekšējo mēnesi; 2) bankas konta izraksts, kurā ir redzami tava darba devēja veiktie algas maksājumi vismaz par pēdējo mēnesi; 3) pagājušā gada nodokļu deklarācija.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'lv-LV', 'Tu norādīji finanšu aktīvu pārdošanu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) investīciju nodrošinātāja apliecinājums; 2) bankas konta izraksts, kurā redzami maksājumi no investīciju nodrošinātāja; 3) citi kontu izraksti vai dokumenti, kas apliecina peļņu no ieguldījumiem vērtspapīros, akcijās utt.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'lv-LV', 'Tu norādīji nekustamā īpašuma vai citu aktīvu pārdošanu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums vienu vai vairākus tālāk norādītos dokumentus verifikācijas pabeigšanai: 1) pārdošanas līgums/norēķinu apliecinājums; 2) parakstīta advokāta/nekustamā īpašuma/notāra vēstule, kas apstiprina īpašuma pārdošanu; 3) Zemes grāmatas sertifikātu kopijas. Papildus vari arī nosūtīt bankas izrakstu, kurā redzami tavā bankas kontā iemaksātie līdzekļi', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'lv-LV', 'Tu norādīji uzkrājumus kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums sava uzkrājumu konta izrakstu (ne vecākas par 3 mēnešiem).', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'lv-LV', 'Tu norādīji pašnodarbinātā darbu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums nodokļu deklarāciju par iepriekšējo gadu. Tāpat vari atsūtīt mums jaunākos rēķinus/līgumus par pašnodarbinātās personas sniegtajiem pakalpojumiem vai peļņas/zaudējumu pārskatus, kas apliecina gada vai mēneša ienākumus', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'lv-LV', 'Tu norādīji uzņēmuma peļņu (akcijas/dividendes) kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums vienu vai vairākus tālāk norādītos dokumentus verifikācijas veikšanai: 1) dividenžu maksājumu izraksti; 2) līgumi par peļņas sadalījumu; 3) bankas konta izraksts, kurā ir redzami dividenžu maksājumi; 4) jaunākais veiktais uzņēmuma kontu audits.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'lv-LV', 'Kriptovalūtu ieguldījumu verifikācija: tavi iesniegtie pierādījumi tam, ka kriptovalūtas ir tavs galvenais līdzekļu izcelsmes avots, nav pietiekami. Lūdzu, veic papildu verifikāciju, iesniedzot izrakstus no citām biržām, bezsaistes maku ekrānuzņēmumus, kriptovalūtu pirkumu kvītis vai citus atbilstošus dokumentus. Taviem iesniegtajiem pamatojuma dokumentiem ir jāatbilst mūsu sistēmā iesniegtajai deklarācijai.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'lv-LV', 'Tu norādīji ziedojumus kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) līgums par nekustamā īpašuma vai citu aktīvu ziedošanu; 2) donora parakstīts apliecinājums/vēstule, kurā norādīta dāvana; 3) bankas konta izraksts, kurā redzama ziedojuma iemaksa kontā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'lv-LV', 'Tu norādīji finanšu ieguldījumus kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) investīciju nodrošinātāja apliecinājums; 2) bankas konta izraksts, kurā redzami maksājumi no investīciju nodrošinātāja; 3) citi kontu izraksti vai dokumenti, kas apliecina peļņu no ieguldījumiem vērtspapīros, akcijās utt.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'lv-LV', 'Tu norādīji mantojumu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums tālāk norādīto, lai pabeigtu tavu verifikāciju: 1) novēlējuma/testamenta kopiju; 2) testamenta izpildītāja(advokāts/notārs u.tml.) parakstītu vēstuli.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'lv-LV', 'Tu norādīji hipotēkas/aizdevumus kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti tālāk norādīto, lai pabeigtu tavu verifikāciju: hipotēkas/aizdevuma līgums, kurā ir redzama aizdevuma summa un atmaksas plāns, UN bankas konta izraksts, kurā ir redzama aizdevuma/hipotēkas iemaksa tavā kontā.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'lv-LV', 'Tu norādīji algu kā savu galveno līdzekļu izcelsmes avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Atsūti mums vienu no tālāk norādītajiem dokumentiem verifikācijas veikšanai: 1) algas maksājumu izraksti, kuros ir redzami tavi ieņēmumi vismaz par iepriekšējo mēnesi; 2) bankas konta izraksts, kurā ir redzami tava darba devēja veiktie algas maksājumi vismaz par pēdējo mēnesi; 3) pagājušā gada nodokļu deklarācija.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'lv-LV', 'Tu norādīji pašnodarbinātā darbu kā savu galveno ienākumu avotu, bet iesniegtie dokumenti nav pietiekami un neatbilst mūsu prasībām. Lūdzu, atsūti mums nodokļu deklarāciju par iepriekšējo gadu. Tāpat vari atsūtīt mums jaunākos rēķinus/līgumus par pašnodarbinātās personas sniegtajiem pakalpojumiem vai peļņas/zaudējumu pārskatus, kas apliecina gada vai mēneša ienākumus', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'lv-LV', 'Mēs atklājām neatbilstības tavā līdzekļu izcelsmes deklarācijā. Iesniegtie dokumenti uzrāda būtiski lielāku kopējo aktīvu vērtību un neatbilst tai, ko norādīji Binance platformā. Lūdzu, iesniedz mums precīzu informāciju par visu tev piederošo aktīvu kopējo (aptuveno) vērtību un iesniedz pieteikumu vēlreiz. Nepareizas, nepietiekamas vai nepatiesas informācijas norādīšana kavē tava pieteikuma apstiprināšanu.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'lv-LV', 'Izskatot tavu iesniegto deklarāciju, mēs konstatējām būtiskas kļūdas. Lai paātrinātu procesu, lūdzu, iesniedz precīzus un pilnīgus datus par saviem gada (bruto) ienākumiem, kopējo aktīvu apmēru un līdzekļu izcelsmi. Kopā ar deklarāciju, lūdzu, iesniedz atbilstošus pierādījumus. Ja tiks iesniegti nepareizi vai nepietiekami dati, tava pieteikuma izskatīšana var ieilgt. Pateicamies par sadarbību.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'lv-LV', 'Mēs atklājām nepareizu, neatbilstošu vai nepilnīgu informāciju tavā nodarbinātības apliecinājumā. Iesniedz pieteikumu atkārtoti, norādot pareizu informāciju, tai skaitā: 1) nodarbinātības statuss – pašreiz nodarbināts/pašnodarbināts/students/pensijā/cits; 2) darba devēja/uzņēmuma nosaukums – tava darba devēja/uzņēmuma nosaukums; 3) darba davēja/uzņēmuma adrese – darba devēja/uzņēmuma juridiskā adrese. Pārliecinies par to, ka iesniegtā informācija ir aktuāla un atbilst informācijai iesniegtajos dokumentos.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'lv-LV', 'Pamanījām, ka pārskaitīji līdzekļus no cita sava bankas konta. Lūdzu, atsūti mums pēdējos 3 mēnešos izdotu bankas konta izrakstu, kurā ir redzami otra bankas konta darījumi (vismaz 1 mēnesis ar darījumiem).', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'lv-LV', 'Tava fotoattēla kvalitāte nav pietiekami skaidra un neatbilst mūsu redzamības prasībām. Lūdzu, iesniedz attēlu augstākā izšķirtspējā (vismaz 300 DPI), kurā ir redzama pilna lapa ar visiem četriem stūriem kadrā. Vai arī iesniedz citus dokumentus, lai veiktu verifikāciju.', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
