INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'lv-LV', 'Verifikācija neizdevās. Iespējams, ka tas ir drošības apsvērumu dēļ vai tavai valstij/reģionam piemēroto ierobežojumu dēļ. Atvainojamies par sagādātajām neērtībām!', '2023-06-18 18:48:37', '2023-06-18 18:48:37') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
