INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'pl-PL', 'Niezakwalifikowane dokumenty. Wymagane pola dokumentu nie są czytelne lub widoczne. Proszę przesłać nowe zdjęcie. Upewnij się, że zdjęcie jest jasne i wyraźne, a wszystkie rogi dokumentu są widoczne.', '2023-06-18 18:48:38', '2023-06-18 18:48:38') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
