INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'pt-PT', 'Falha na verificação. Poderá dever-se a motivos de segurança ou pelo teu país/região estar restrito. Pedimos desculpa por qualquer inconveniente causado.', '2023-06-18 18:48:40', '2023-06-18 18:48:40') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
