INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ID_INVALID', 'ro-RO', 'Ne pare rău, documentul dvs. de identitate nu este valid și nu poate fi folosit pentru verificare. Încercați un alt document de identitate.', '2023-06-18 18:48:41', '2023-06-18 18:48:41') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
