INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_PEP', 'ro-RO', 'Verificarea nu a reușit. Acest lucru poate fi cauzat de motive de securitate sau de faptul că țara/regiunea dvs. este restricționată. Vă cerem scuze pentru eventualele neplăceri cauzate.', '2023-06-18 18:48:41', '2023-06-18 18:48:41') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_PROBLEMATIC_APPLICANT_DATA', 'ro-RO', 'Introduceți numele și prenumele/data nașterii/adresa așa cum sunt scrise în document.', '2023-06-18 18:48:41', '2023-06-18 18:48:41') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_REGULATIONS_VIOLATIONS', 'ro-RO', 'Verificarea nu a reușit. Acest lucru poate fi cauzat de motive de securitate sau de faptul că țara/regiunea dvs. este restricționată. Vă cerem scuze pentru eventualele neplăceri cauzate.', '2023-06-18 18:48:41', '2023-06-18 18:48:41') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
