INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SELFIE_MISMATCH', 'ro-RO', 'Selfie-ul nu corespunde cu fotografia de pe documentul de identitate.', '2023-06-18 18:48:41', '2023-06-18 18:48:41') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
