INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BLACKLIST', 'sk-SK', 'Overenie zlyhalo. Môže to byť z bezpečnostných dôvodov alebo obmedzenia vo vašej krajine/oblasti. Ospravedlňujeme sa za spôsobené nepríjemnosti.', '2023-06-18 18:48:43', '2023-06-18 18:48:43') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
