INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'sk-SK', 'Nekvalifikované dokumenty. Povinné polia dokladu nie sú čitateľné ani viditeľné. Nahrajte novú fotografiu. Uistite sa, že fotografia je svetlá a jasná, a že sú viditeľné všetky rohy dokumentu.', '2023-06-18 18:48:43', '2023-06-18 18:48:43') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
