INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'sk-SK', 'Ľutujeme, región nie je podporovaný.', '2023-06-18 18:48:43', '2023-06-18 18:48:43') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'sl-SI', 'Preverite dohodek: Predložite dokumentarne dokaze za vse vire dohodka, prijavljene pri Binance, vključno s plačo, dohodki od samozaposlitve, pokojnino, dividendami, trgovanjem, najemnino ali drugimi dohodki. Predložite zadostna in točna dokazila, ki se ujemajo z vašim prijavljenim dohodkom. Nepravilne ali nezadostne informacije ovirajo odobritev.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'sl-SI', 'Predložite najnovejši bančni izpisek (izdan v zadnjih 3 mesecih). Vsebovati mora vaše ime, ime/logotip izdajatelja in vašo zgodovino transakcij, ki jasno prikazuje mesečna nakazila vašega delodajalca, storitve iz naslova samostojnega podjetnika, pokojnino, dodatke, dividende, dvige dobička iz trgovanja ali iger na srečo, najemnino ali katera koli druga redna nakazila, ki prikazujejo vaš celoten letni dohodek, prijavljen pri Binance. Te dokumente raje sprejemamo v digitalni oz .pdf obliki ali kot cele fotografije fizičnih izjav.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'sl-SI', 'Naloženi dokumentarni dokazi ne prikazujejo jasno datuma izdaje in jih ni mogoče sprejeti.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'sl-SI', 'Naložili ste dokumente, na katerih vaši osebni podatki niso vidni. Poskrbite, da bodo vaše polno ime, datum izdaje in morebitni logotipi izdajatelja prikazani na podpornih dokumentih.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'sl-SI', 'Vaših dokumentarnih dokazov (izdanih z imeni tretjih oseb) ni mogoče sprejeti kot dokumentacijo za preverjanje vira premoženja ali vira sredstev. Naložite dokumente, izdane z vašim osebnim imenom, ali zagotovite pojasnilo o tem, kako je mogoče dokumente tretjih oseb uporabiti za preverjanje vaše dejavnosti fiat ali skupne vrednosti premoženja.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'sl-SI', 'Dragi uporabnik platforme Binance, vaša prijava je bila odobrena. Uživajte v vlaganju s platformo Binance!', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'sl-SI', 'Preden pošljete potrditev vira premoženja ali vira sredstev, se prepričajte, da ste dokončali postopek preverjanja istovetnosti. Postopek lahko dokončate tako, da odprete zavihek za preverjanje istovetnosti in naložite veljaven potni list ali kateri koli drug sprejemljiv osebni dokument, odvisno od lokalnih zahtev.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'sl-SI', 'Spoštovani uporabnik, družba Binance je za vse svoje uporabniške račune zagotovila nove fiat omejitve v vrednosti 2 milijona USD na dan. Vaša trenutna zahteva za povečanje omejitve (na 500.000/1 mil./2 mil. USD) se zato šteje za nepotrebno. Uživajte v trgovanju!', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'sl-SI', 'Vaše prijave žal nismo mogli preveriti s predloženimi dokazili. Da bi vam lahko dodatno pomagali, vas vabimo na pogovor s predstavnikom našega oddelka za skladnost. V nekaj minutah boste prejeli e-poštno sporočilo s povabilom. Za nadaljevanje kliknite gumb »Začnite pogovor zdaj«.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'sl-SI', 'Naloženi dokumentarni dokazi niso dovolj jasni in ne izpolnjujejo naših zahtev glede vidnosti. Naložite izvirni dokument. Te dokumente raje sprejemamo v digitalni oz .pdf obliki ali celotne fotografije fizičnih izjav, pri čemer so vidni vsi štirje vogali dokumenta.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'sl-SI', 'Prosimo, da v obrazec izjave PIO vnesete točne odgovore. Sporočite nam, ali ste razvrščeni kot PIO ali ne, svoje polno ime, položaj, razmerje (če ste PIO po združenju) in koliko časa ste PIO. Ko vnesete te podatke, lahko ponovno oddate prijavo.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'sl-SI', 'Preden pošljete potrditev vira premoženja ali vira sredstev, se prepričajte, da ste dokončali postopek preverjanja naslova. Ta postopek lahko dokončate tako, da odprete zavihek za preverjanje identitete in naložite veljaven bančni izpisek/račun za komunalne storitve/davčni dokument, izdan v zadnjih treh mesecih, na vaše ime in s točnim naslovom.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali nadomestilo, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) bančni izpisek, ki prikazuje nakazila nadomestila za zadnje 3 mesece; 2) izkaz državnega nadomestila ali izpisek drugih socialnih prejemkov.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'sl-SI', 'Izjavili ste, da vaš vir sredstev izhaja iz prodaje sredstev. Prosimo, predložite bančni izpisek, ki prikazuje prejeto plačilo od prodaje vašega premoženja, ki je bilo nakazano na vaš bančni račun, z jasno navedenim imenom in datumom izdaje v 3 mesecih od vaše prijave. Te dokumente raje sprejemamo v digitalni oz .pdf obliki ali kot cele fotografije fizičnih izjav.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'sl-SI', 'Izjavili ste, da sredstva na vašem računu izhajajo iz dejavnosti kriptorudarjenja. Za podporo vaše prijave, nam posredujte: 1) dokazilo o nakupu strojne opreme, ki se uporablja za rudarjenje (ki prikazuje tako vaše podatke kot tudi podatke prodajalca); 2) dokazilo o vseh prihodkih od rudarjenja z ustreznih platform(-e)/borz(-e). V vsakem primeru potrebujemo posnetke zaslona za vsaj 3-mesečno zgodovino transakcij, ki podrobno prikazujejo vse dejavnosti z rudarjenimi kovanci ter obenem prikazujejo naslove denarnic in ID-je transakcij. Te je treba posneti na ustrezni platformi/borzi in vključiti podatke o vašem računu.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali dnevno trgovanje, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) izpiske transakcij, ki dokazujejo vašo trgovalno dejavnost v zadnjem mesecu IN bančni izpisek, ki prikazuje dvige dobička, položene na vaš račun. Oba dokumenta morata vsebovati podatke o registraciji računa in logotip izdajatelja; 2) davčno napoved za preteklo davčno leto, ki dokazuje vaš dohodek iz dobička iz trgovanja.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali izplačila dividend/dobiček podjetja, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več naslednjih dokumentov: 1) izpiski dividend; 2) distribucijski sporazumi; 3) bančni izpisek, ki prikazuje izplačilo dividend; 4) najnovejša revizija računovodskih izkazov podjetja.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali donacije, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) darilno pogodbo za nepremičnino ali druga sredstva; 2) podpisano izjavo/pismo darovalca, ki opisuje naravo darila; 3) bančni izpisek, ki prikazuje bančni polog donacije.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali igre na srečo, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) izpiske transakcij, ki dokazujejo vašo igralniško dejavnost v zadnjem mesecu IN bančni izpisek, ki prikazuje dvige dobička, položene na vaš račun. Oba dokumenta morata vsebovati podatke o registraciji računa in logotip izdajatelja; 2) davčno napoved za preteklo davčno leto, ki dokazuje vaš dohodek iz iger na srečo.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali dediščino, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjega: 1) kopijo oporoke; 2) podpisano pismo izvršitelja oporoke (odvetnik/pravni zastopnik/podeljevalec zapuščine).', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali posojila/hipoteke, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja pošljite naslednje: posojilno/hipotekarno pogodbo, ki prikazuje znesek posojila in načrt odplačevanja TER bančni izpisek, ki prikazuje pologe posojila/hipoteke na vašem računu.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali pasivni dohodek, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) podpisano najemno/zakupno pogodbo IN nekaj od naslednjega: a. bančni izpisek, ki prikazuje plačilo zadnje najemnine; b. najnovejša potrdila o najemnini/zakupnini; 2) vse druge dokumente, ki dokazujejo vaš pasivni dohodek (npr. licenčnine za knjige, napotitveno trženje, zastavljanje itd.) za zadnji mesec.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali pokojnino, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) bančni izpisek, ki prikazuje nakazila pokojnine za zadnje 3 mesece; 2) pokojninski obračun, ki ga izda država; 3) izpiski pokojninskega sklada.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali plačo, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) plačilne liste, ki prikazujejo vaš dohodek vsaj v zadnjem mesecu; 2) bančni izpisek, ki prikazuje izplačila plače vašega delodajalca vsaj za zadnji mesec; 3) davčni obračun preteklega davčnega leta.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali prodajo finančnih sredstev, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite eno ali več od naslednjega: 1) izjavo vašega ponudnika naložbe; 2) bančni izpisek, ki prikazuje poravnave vašega ponudnika naložb; 3) druge izjave ali listine, ki dokazujejo naložbeni dobiček iz obveznic, delnic itd.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali prodajo nepremičnine ali drugih sredstev, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite eno ali več od naslednjega: 1) prodajno pogodbo/izjavo o poravnavi; 2) podpisano pismo odvetnika/odvetnika/nepremičninskega agenta, ki potrjuje prodajo nepremičnine; 3) zemljiškoknjižni/lastninski list. Poleg tega nam lahko pošljete tudi bančni izpisek, ki prikazuje polog sredstev iz prodaje na vaš bančni račun.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali igre na srečo, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Pošljite nam izpisek varčevalnega računa (izdan v zadnjih 3 mesecih).', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'sl-SI', 'Za svoj glavni vir sredstev ste izbrali samozaposlitev, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Prosimo, pošljite nam davčno napoved za prejšnje davčno leto. Poleg tega nam lahko pošljete nedavne račune/pogodbe za storitve samostojnega podjetnika ali izkaze poslovnega izida, ki dokazujejo mesečne ali letne prihodke.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali dobičke podjetja (delnice/dividende), vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več naslednjih dokumentov: 1) izpiski dividend; 2) distribucijski sporazumi; 3) bančni izpisek, ki prikazuje izplačilo dividend; 4) najnovejša revizija računovodskih izkazov podjetja.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'sl-SI', 'Preverite naložbo v kriptosredstva: dokazi, ki ste jih predložili o tem, da so kriptosredstva vaš glavni vir premoženja, so nezadostni. Zagotovite dodatno preverjanje s predložitvijo izjav z drugih borz, posnetkov zaslona hladnih denarnic, potrdil o nakupu kriptovalut ali drugih ustreznih dokumentov. Poskrbite, da se predloženi dokazi ujemajo z vašo izjavo v našem sistemu.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali donacije, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) darilno pogodbo za nepremičnino ali druga sredstva; 2) podpisano izjavo/pismo darovalca, ki opisuje naravo darila; 3) bančni izpisek, ki prikazuje bančni polog donacije.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali finančno vlaganje, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite eno ali več od naslednjega: 1) izjavo vašega ponudnika naložbe; 2) bančni izpisek, ki prikazuje poravnave vašega ponudnika naložb; 3) druge izjave ali listine, ki dokazujejo naložbeni dobiček iz obveznic, delnic itd.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali dediščino, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjega: 1) kopijo oporoke; 2) podpisano pismo izvršitelja oporoke (odvetnik/pravni zastopnik/podeljevalec zapuščine).', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali posojila/hipoteke, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja pošljite naslednje: hipotekarno/posojilno pogodbo, ki prikazuje znesek posojila in načrt odplačevanja TER bančni izpisek, ki prikazuje pologe posojila/hipoteke na vašem računu.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali plačo, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Za dokončanje preverjanja nam pošljite enega ali več od naslednjih dokumentov: 1) plačilne liste, ki prikazujejo vaš dohodek vsaj v zadnjem mesecu; 2) bančni izpisek, ki prikazuje izplačila plače vašega delodajalca vsaj za zadnji mesec; 3) davčni obračun preteklega davčnega leta.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'sl-SI', 'Za svoj glavni vir premoženja ste izbrali samozaposlitev, vendar predloženi dokumentarni dokazi ne zadostujejo in ne izpolnjujejo naših zahtev. Prosimo, pošljite nam davčno napoved za prejšnje davčno leto. Poleg tega nam lahko pošljete nedavne račune/pogodbe za storitve samostojnega podjetnika ali izkaze poslovnega izida, ki dokazujejo mesečne ali letne prihodke.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'sl-SI', 'Ugotovili smo neskladje v vaši splošni prijavi premoženja. Predloženi dokumentarni dokazi kažejo na znatno višjo vrednost skupnih sredstev in ne ustrezajo tisti, ki ste jo prijavili pri Binance. Prosimo, da nam posredujete točne podatke o vaši celotni (približni) skupni vrednosti vseh sredstev v lasti in ponovno oddate svojo vlogo. Posredovanje napačnih, nezadostnih ali zavajajočih informacij preprečuje takojšnjo odobritev vaše prijave.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'sl-SI', 'Po pregledu vaše izjave smo našli pomembne napake. Poskrbite za hiter postopek in zagotovite točne in popolne podatke o vašem letnem dohodku (bruto), celotnem premoženju in virih premoženja. K izjavi predložite ustrezne dokaze. Napačne ali nezadostne informacije bodo ovirale vašo prijavo. Hvala za sodelovanje.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'sl-SI', 'Odkrili smo nepravilne, neujemajoče se ali nepopolne podatke v vaši izjavi o zaposlitvi. Ponovno pošljite prijavo s točnimi podatki, vključno z: 1) statusom zaposlitve – trenutni status: zaposlen/samozaposlen/študent/upokojenec/drugo; 2) imenom delodajalca/podjetja – ime podjetja/poslovno ime vašega delodajalca; 3) naslovom delodajalca/poslovnim naslovom – prijavljen delodajalec/poslovni naslov. Zagotovite, da so predloženi podatki posodobljeni in da se ujemajo s podatki, navedenimi v vaših dokumentarnih dokazih.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'sl-SI', 'Opazili smo prenos sredstev z vašega drugega bančnega računa. Pošljite nam bančni izpisek, izdan v zadnjih 3 mesecih, ki prikazuje zgodovino transakcij drugega računa (zajemati mora vsaj 1 mesec transakcij).', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'sl-SI', 'Kakovost vaše fotografije ni jasna in ne izpolnjuje naših zahtev glede vidnosti. Ponovno pošljite fotografijo v višji ločljivosti (vsaj 300 DPI), ki prikazuje celotno stran dokumenta s vsemi štirimi vogali, zajetimi v fotografijo. Lahko pa predložite druga dokazila za dokončanje preverjanja.', '2023-06-18 18:48:44', '2023-06-18 18:48:44') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADDITIONAL_DOCUMENT_REQUIRED', 'sl-SI', 'Potrebni so dodatni dokumenti za izvedbo preverjanja.
