INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'sv-SE', 'Det gick inte att verifiera. Detta kan bero på säkerhetsskäl eller att ditt land är begränsat/din region är begränsad. Vi beklagar besväret.', '2023-06-18 18:48:47', '2023-06-18 18:48:47') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
