INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'sv-SE', 'Okvalificerade dokument. De obligatoriska fälten i dokumentet är inte läsbara eller synliga. Ladda upp ett nytt foto. Se till att fotot är ljust och klart och att alla hörn av dokumentet är synliga.', '2023-06-18 18:48:47', '2023-06-18 18:48:47') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
