INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'sv-SE', 'Tyvärr, regionen stöds inte.', '2023-06-18 18:48:47', '2023-06-18 18:48:47') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'tr-TR', 'Gelirinizi Doğrulayın: Maaş, serbest meslek kazancı, emekli maaşı, temettüler, alım satım, kira veya diğer gelirler de dahil olmak üzere Binancee beyan edilen tüm gelir kaynaklarına ilişkin belgeli kanıt sunun. Beyan ettiğiniz gelirle eşleşen yeterli miktarda ve doğru destekleyici belge gönderin. Yanlış veya yetersiz bilgiler onayı geciktirir.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'tr-TR', 'Lütfen bize güncel (son 3 ay içinde düzenlenmiş) bir banka ekstresi gönderin. Ekstreniz adınızı, belgeyi düzenleyenin adını/logosunu ve işvereninizden gelen aylık transferleri, serbest meslek hizmetlerini, emekli aylıklarınızı, ödeneklerinizi, temettülerinizi, alım satım ya da şans oyunlarından elde edilen kâr çekimlerinizi, düzenli aralıklarla alınan kira ya da diğer herhangi bir transferi açıkça gösteren ve Binancee beyan edilen tam yıllık gelirinizi ifade eden işlem geçmişinizi içermelidir. Bu belgeleri dijital bir .pdf olarak veya fiziksel ekstrelerin tam fotoğrafları formatında almayı tercih ederiz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'tr-TR', 'Yüklenen kanıt belgesinde net bir düzenlenme tarihi görünmüyor ve belge kabul edilemiyor.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'tr-TR', 'Kişisel bilgilerinizin görünür olmadığı belgeler yüklediniz. Destekleyici belgelerde tam adınızın, düzenlenme tarihinin ve düzenleyenin logosunun gözüktüğünden lütfen emin olun.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'tr-TR', 'Kanıt belgeniz (üçüncü taraf isimleri ile düzenlenmiş olan) Servet Kaynağı veya Fon Kaynağı doğrulama belgesi olarak kabul edilemiyor. Lütfen kişisel adınız ile düzenlenmiş olan belgeleri yükleyin ya da üçünü taraf belgelerinin itibari para etkinliklerinizi veya toplam varlık değerinizi doğrulamak için nasıl kullanılabileceğine dair bir açıklama sağlayın.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'tr-TR', 'Değerli Binance Kullanıcısı, başvurunuz onaylandı. Binance ile yatırım yapmanın keyfini çıkarın!', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'tr-TR', 'Bir Servet Kaynağı veya Fon Kaynağı doğrulaması göndermeden önce kimlik doğrulaması işlemini tamamladığınızdan emin olun. Bu işlemi, kimlik doğrulama sekmesine giderek ve yerel gerekliliklere göre geçerli bir pasaport veya kabul edilen herhangi bir kimlik belgesi yükleyerek tamamlayabilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'tr-TR', 'Değerli Kullanıcı, Binance tüm kullanıcı hesaplarımızda günlük 2 milyon USD değerinde yeni itibari para limitleri sunmuştur. Bu nedenle, mevcut limit artırma talebiniz (500 bin/1 milyon/2 milyon USD için) gereksiz olarak değerlendirilmiştir. Alım satımın tadını çıkarın!', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'tr-TR', 'Ne yazık ki sunmuş olduğunuz kanıtlarla başvurunuzu doğrulayamadık. Daha fazla yardımcı olabilmek için sizleri uyum departmanımızla bir sohbete davet etmek isteriz. Birkaç dakika içinde bir davet e-postası alacaksınız. Lütfen devam etmek için "Hemen Sohbete Başla" düğmesine tıklayın.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'tr-TR', 'Yüklenen kanıt belgeleri yeterince net değil ve bizim görünürlük gerekliliklerimizi karşılamıyor. Lütfen orijinal belgeyi yükleyin. Bu belgeleri dijital bir .pdf formatında veya belgenin dört köşesi de görünecek şekilde fiziksel ekstrelerin tam fotoğrafları olarak almayı tercih ediyoruz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'tr-TR', 'Lütfen PEP Beyanı formumuzu doğru yanıtlarla doldurun. Bir PEP olarak sınıflandırılıp sınıflandırılmadığınızı, tam adınızı, pozisyonunuzu, ilişkinizi (bir kuruluş aracılığıyla PEP iseniz) ve ne kadar süredir PEP olduğunuzu bize bildirin. Bu bilgileri sunduktan sonra başvurunuzu yeniden gönderebilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'tr-TR', 'Bir Servet Kaynağı veya Fon Kaynağı doğrulaması göndermeden önce Adres Belgesi doğrulaması işlemini tamamladığınızdan emin olun. Bu işlemi, kimlik doğrulama sekmesine giderek ve son üç ay içinde adınıza düzenlenmiş ve doğru bir adresin görünür olduğu geçerli bir banka ekstresi/hizmet faturası/vergi belgesi yükleyerek tamamlayabilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'tr-TR', 'Ana Fon Kaynağınız olarak Ödenek seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Son 3 aya ait ödenek transferlerini gösteren bir banka ekstresi; 2) Devlet tarafından düzenlenmiş bir ödenek ya da herhangi bir sosyal yardım belgesi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'tr-TR', 'Fon kaynağınızın Varlık satışından geldiğini beyan ettiniz. Lütfen adınızın açık bir biçimde görüldüğü ve düzenlenme tarihi başvuru tarihinizden itibaren 3 ay içinde olan, varlıklarınızın satışından banka hesabınıza gelen ödemeleri gösteren bir banka ekstresi sunun. Bu belgeleri bir dijital .pdf olarak veya fiziksel ekstrelerin tam fotoğrafları formatında almayı tercih ederiz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'tr-TR', 'Hesabınızdaki fonların kripto madenciliği faaliyetlerinden geldiğini beyan ettiniz. Başvurunuzu desteklemek için lütfen şu ikisinden birini sunun: 1) Madencilik için kullanılan donanımın satın alımının ispatı (hem sizin hem de satıcının bilgilerini gösteren); 2) İlgili platformlardan/borsalardan gelen tüm madencilik gelirlerinin ispatı. Her iki durumda da çıkarılan coinlerle olan tüm etkinliklerin bilgilerini veren ve cüzdan adresleri ile işlem kimliklerini gösteren, en az 3 aylık işlem geçmişinin ekran görüntülerini talep ediyoruz. Bunlar, ilgili platformdan/borsadan alınmış olmalı ve hesap bilgilerinizi içermelidir.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'tr-TR', 'Ana Fon Kaynağınız olarak Günlük alım satım seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Geçen ay için olan alım satım etkinliklerinizi gösteren işlem dökümleri VE hesabınıza yatırılmış olan kâr çekimlerini gösteren bir banka ekstresi. Her iki belgede de hesap kayıt bilgileri ve belgeyi düzenleyenin logosunu görünmelidir; 2) Alım satım kârlarından doğan gelirinizi gösteren önceki yıla ait bir vergi beyannamesi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'tr-TR', 'Ana Fon Kaynağınız olarak Bir şirketten elde edilen Temettü ödemeleri/Kârlar seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Temettü belgeleri; 2) Dağıtım sözleşmeleri; 3) Temettü ödemelerini gösteren bir banka ekstresi; 4) Şirket hesaplarının en güncel denetimi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'tr-TR', 'Ana Fon Kaynağınız olarak Hibeler seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Gayrimenkul veya diğer varlıklar için hibe sözleşmesi; 2) Hibenin cinsinin beyan edildiği, hibe edenden alınan imzalı yeminli ifade/belge; 3) Hibenin banka hesabına yatırıldığını gösteren banka ekstresi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'tr-TR', 'Ana Fon Kaynağınız olarak Şans Oyunları seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Şans oyunları etkinliklerinizi gösteren geçen aya ait işlem dökümleri VE hesabınıza yatırılmış olan kâr çekimlerini gösteren bir banka ekstresi. Her iki belgede de hesap kayıt bilgileri ve belgeyi düzenleyenin logosu görünmelidir; 2) Şans oyunları kârlarından doğan gelirinizi gösteren önceki yıla ait bir vergi beyannamesi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'tr-TR', 'Ana Fon Kaynağınız olarak Miras seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Vasiyetin/vasiyetnamenin bir nüshası; 2) Vasiyeti uygulayan kişiden imzalı bir belge (avukat/hukuk müşaviri/vasiyetnamenin onaylandığı gösteren kararın verildiği kişi).', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'tr-TR', 'Ana Fon Kaynağınız olarak Krediler/İpotekler seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunları tarafımıza gönderin: Kredi tutarını ve geri ödeme planını gösteren bir kredi/ipotek sözleşmesi VE hesabınıza yatırılan kredi/ipotekleri gösteren bir banka ekstresi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'tr-TR', 'Ana Fon Kaynağınız olarak Pasif gelir seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) İmzalanmış bir kira/finansal kiralama sözleşmesi VE şunlardan biri: a. En son kira/finansal kiralama ödemesini gösteren banka ekstresi; b. En güncel kira/finansal kiralama makbuzları; 2) Geçen aya ait pasif gelirinizi gösteren diğer herhangi bir belge (ör. kitap telif hakları, affiliate pazarlaması, staking vb.)', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'tr-TR', 'Ana Fon Kaynağınız olarak Emekli Aylığı seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Son 3 aya ait emekli aylığı transferlerini gösteren bir banka ekstresi; 2) Devlet tarafından düzenlenmiş bir emekli aylığı belgesi 3) Emekli aylığına ilişkin belgeler.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'tr-TR', 'Ana Fon Kaynağınız olarak Maaş seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) En az son bir aydan itibaren olan gelirinizi gösteren maaş bordroları; 2) En az son bir aydan itibaren olan işvereninizden gelen maaş ödemelerini gösteren bir banka ekstresi; 3) Bir önceki vergi yılına ait vergi beyannamesi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'tr-TR', 'Ana Fon Kaynağınız olarak Finansal varlıkların satışı seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Yatırım hizmeti sağlayıcınızdan bir hesap ekstresi; 2) Yatırım hizmeti sağlayıcınızdan alınan ödemeleri gösteren bir banka ekstresi; 3) Tahvil, hisse senedi vb.den gelen yatırım kârını gösteren diğer ekstreler veya belgeler.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'tr-TR', 'Ana Fon Kaynağınız olarak Gayrimenkul veya diğer varlıkların satışı seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Satış sözleşmesi/ödeme belgesi; 2) Mülk satışının yapıldığını doğrulayan, bir hukuk müşavirinden/avukattan/emlakçıdan alınan imzalı belge; 3) Tapu kaydı/tapu senedi nüshaları. Ayrıca, bize banka hesabınıza satış fonlarının yatırıldığını gösteren bir banka ekstresi gönderebilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'tr-TR', 'Ana Fon Kaynağınız olarak Birikimler seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Bize lütfen bir birikim hesabından (son 3 ay içinde düzenlenmiş) bir ekstre gönderin.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'tr-TR', 'Ana Fon Kaynağınız olarak Serbest Meslek seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Lütfen tarafımıza önceki vergi yılına ait bir vergi beyannamesi gönderin. Ek olarak, aylık veya yıllık kazancınızı kanıtlamak için bize serbest meslek hizmetlerinize ait en son faturaları/sözleşmeleri/anlaşmaları veya kâr/zarar belgelerini gönderebilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'tr-TR', 'Servet Kaynağınız olarak Şirket kârları (hisseler/temettüler) seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını bize gönderin: 1) Temettü belgeleri; 2) Dağıtım sözleşmeleri; 3) Temettü ödemelerini gösteren bir banka ekstresi; 4) Şirket hesaplarının en güncel denetimi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'tr-TR', 'Kripto Yatırımını Doğrulayın: Ana servet kaynağı olarak Kriptoya dair sunduğunuz kanıtlar yetersizdir. Diğer borsalardan alınan hesap özetleri, soğuk cüzdanların ekran görüntüleri, kripto satın alma makbuzları veya her türlü ilgili belgeyi göndererek ek doğrulama sunun. Sunduğunuz kanıtların sistemimizdeki beyanınızla eşleştiğinden emin olun.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'tr-TR', 'Servet Kaynağınız olarak Hibe seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Gayrimenkul veya diğer varlıklar için hibe sözleşmesi; 2) Hibenin cinsinin beyan edildiği, hibe edenden alınan imzalı yeminli ifade/belge; 3) Hibenin banka hesabına yatırıldığını gösteren banka ekstresi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'tr-TR', 'Servet Kaynağınız olarak Mali yatırım seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen bize şunlardan birini ya da daha fazlasını gönderin: 1) Yatırım hizmeti sağlayıcınızdan alınan bir hesap ekstresi; 2) Yatırım hizmeti sağlayıcınızdan alınan, ödemeleri gösteren bir banka ekstresi; 3) Tahvil, hisse senedi vb.den gelen yatırım kârını gösteren diğer ekstreler veya belgeler.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'tr-TR', 'Servet Kaynağınız olarak Miras seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şunlardan birini ya da daha fazlasını tarafımıza gönderin: 1) Vasiyetin/vasiyetnamenin bir nüshası; 2) Vasiyeti uygulayan kişiden imzalı bir belge (avukat/hukuk müşaviri/vasiyetnamenin onaylandığı gösteren karar).', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'tr-TR', 'Servet Kaynağınız olarak İpotek/Krediler seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen şu bilgileri tarafımıza gönderin: İpotek veya kredi değerini ve geri ödeme planını gösteren bir ipotek/kredi sözleşmesi VE hesabınıza yatırılan kredi/ipotekleri gösteren bir banka ekstresi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'tr-TR', 'Servet Kaynağınız olarak Maaş seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Doğrulamanızı tamamlamak için lütfen bize şunlardan birini ya da daha fazlasını gönderin: 1) En az son bir aya kadar olan gelirinizi gösteren maaş bordroları; 2) En az son bir aya kadar olan, işvereninizden gelen maaş ödemelerini gösteren bir banka ekstresi; 3) Bir önceki vergi yılına ait vergi beyannamesi.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'tr-TR', 'Servet Kaynağınız olarak Serbest Meslek seçeneğini seçtiniz ancak sunmuş olduğunuz kanıt belgeleri yeterli değil ve gerekliliklerimizi karşılamıyor. Lütfen bize önceki vergi yılına ait bir vergi beyannamesi gönderin. Ek olarak, aylık veya yıllık kazancınızı kanıtlamak için bize serbest meslek hizmetlerinize ait en son faturaları/sözleşmeleri/anlaşmaları veya kâr/zarar belgelerini gönderebilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'tr-TR', 'Genel servet beyanınızda bir uyuşmazlık tespit ettik. Sunulan kanıt belgeleri önemli ölçüde daha yüksek bir Toplam Servet değeri göstermekte ve Binancee sunmuş olduğunuz değer ile eşleşmemektedir. Sahip olduğunuz tüm varlıkların genel (yaklaşık) toplam değeri hakkında lütfen bize doğru bilgi sağlayın ve başvurunuzu yeniden gönderin. Yanlış, yetersiz ya da yanıltıcı bilgi vermek başvurunuzun hızlı bir şekilde onaylanmasına engel olur.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'tr-TR', 'Beyanınızı incelememizin sonucunda önemli hatalar tespit ettik. Sürecin hızlı olmasını sağlamak için yıllık gelirinize (brüt), toplam mal varlığınıza ve servet kaynaklarınıza dair doğru ve eksiksiz bilgi sağlayın. Lütfen beyanınız ile birlikte yeterli miktarda kanıt da sunun. Yanlış veya yetersiz bilgiler başvurunuzu geciktirir. İş birliğiniz için teşekkür ederiz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'tr-TR', 'Çalışma bilgileri beyanınızda yanlış, eşleşmeyen veya tam olmayan bilgiler tespit ettik. Lütfen formu aşağıdakiler de dahil olmak üzere doğru bilgilerle doldurup başvurunuzu yeniden gönderin: 1) Çalışma durumunuz - mevcut Çalışan/Serbest Meslek Sahibi/Öğrenci/Emekli/Diğer durumu; 2) İşveren/Şirket adı - İşvereninizin Şirketinin/İşletmesinin adı; 3) İşveren/Şirket adresi - İşverenin/Şirketin kayıtlı adresi. Vermiş olduğunuz bilgilerin güncel olduğundan ve kanıt belgelerinizde sunduğunuz bilgilerle eşleştiğinden emin olun.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'tr-TR', 'Diğer banka hesabınızdan fon transferi yapıldığını tespit ettik. Lütfen bize diğer hesabın (en az 1 aylık işlemlerini içeren) işlem geçmişini gösteren, son 3 ay içinde düzenlenmiş olan bir banka ekstresini gönderin.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'tr-TR', 'Fotoğrafınızın görüntü kalitesi net değil ve görünürlük gerekliliklerimizi karşılamıyor. Lütfen belgenin dört köşesini kadraja dahil ederek tam sayfayı gösteren, daha yüksek çözünürlükte (en az 300 DPI) bir kopya gönderin. Alternatif olarak doğrulamanızı tamamlamak için başka belgeler sunabilirsiniz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
