INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'tr-TR', 'Doğrulama başarısız. Bu durumun sebebi güvenlik veya ülkenizin/bölgenizin kısıtlanmış olması olabilir. Vermiş olduğumuz rahatsızlıktan ötürü özür dileriz.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
