INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'tr-TR', 'Geçersiz belgeler. Belgenin zorunlu alanları okunamıyor veya görünmüyor. Lütfen yeni bir fotoğraf yükleyin. Fotoğrafın uygun ışık koşullarında çekilmiş ve net olduğundan ve belgenin tüm köşelerinin görünür olduğundan emin olun.', '2023-06-18 18:48:48', '2023-06-18 18:48:48') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
