INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'uk-UA', 'Документи не відповідають вимогам. Обов’язкові поля документа не читаються або їх погано видно. Будь ласка, завантажте нове фото. Упевніться, що ваша фотографія чітка і яскрава, а всі кути документа добре видно.', '2023-06-18 18:48:49', '2023-06-18 18:48:49') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
