INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'ur-PK', 'آمدنی کی توثیق کریں: Binance کو بیان کردہ آمدنی کے تمام ذرائع کے دستاویزی ثبوت فراہم کریں، بشمول تنخواہ، آزاد پیشہ، پنشن، منافع، ٹریڈنگ، کرایہ، یا دیگر آمدنی۔ ایسی کافی اور درست معاونتی دستاویزات جمع کروائیں جو آپ کی بیان کردہ آمدنی کی توثیق کریں۔ نادرست یا ناکافی معلومات منظوری میں تاخیر کا باعث ہوں گی۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'ur-PK', 'براہِ کرم بینک کی ایک حالیہ اسٹیٹمنٹ (جو گزشتہ 3 مہینوں میں جاری ہوئی تھی) فراہم کریں۔ اس میں لازمی طور پر آپ کا نام، اجرا کنندہ کا نام/لوگو، اور آپ کی ٹرانزیکشن ہسٹری موجود ہونی چاہیئے، جو واضح انداز میں آپ کے آجر، آزاد پیشے کی سروسز، پینشن، الاؤنسز، منافع جات، ٹریڈنگ یا جوئے کے منافع نکلوانے، کرائے یا، کسی دیگر ٹرانسفرز سے باقاعدگی سے ماہانہ بنیاد پر موصول ہونے والی ایسی ٹرانسفرز کو ظاہر کرے، جو آپ کی Binance کے ساتھ بیان کردہ مکمل سالانہ آمدنی کو ظاہر کرتی ہے۔ ہم اس بات کو ترجیح دیتے ہیں کہ ہمیں یہ دستاویزات ڈیجیٹل .pdf یا مادی اسٹیٹمنٹس کی مکمل تصاویر کے طور پر موصول ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'ur-PK', 'اپلوڈ کیے جانے والا دستاویزی ثبوت تاریخِ اجراء واضح انداز میں ظاہر نہیں کرتا اور اسے قبول نہیں کیا جا سکتا۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'ur-PK', 'آپ نے ایسے مقام پر دستاویزات اپلوڈ کی ہیں، جہاں آپ کی ذاتی تفصیلات نظر نہیں آ رہیں۔ براہِ کرم یہ یقینی بنائیں کہ معاونتی دستاویزات میں آپ کا مکمل نام، تاریخِ اجراء، اور اجراء کنندہ کے کوئی بھی لوگوز ظاہر ہو رہے ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'ur-PK', 'آپ کے دستاویزی ثبوت (جو فریقِ ثالث کے ساتھ جاری کیا گیا ہو) کو آپ کے دولت کے ذرائع یا فنڈز کے ذرائع کی توثیقی دستاویز سازی کے طور پر قبول نہیں کیا جا سکتا۔ براہِ کرم اپنے ذاتی نام کے ساتھ اجراء کردہ دستاویزات اپلوڈ کریں، یا اس امر کی وضاحت پیش کریں کہ آپ کی فیاٹ سرگرمی یا کُل اثاثہ جاتی مالیت کی توثیق کے لیے فریقِ ثالث کی دستاویزات کو کیسے استعمال کیا جا سکتا ہے۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'ur-PK', 'معزز Binancian، آپ کی درخواست منظور ہو گئی ہے۔ Binance میں سرمایہ کاری کرنے سے لطف اندوز ہوں!', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'ur-PK', 'دولت کا ذریعہ بھیجنے یا فنڈز کے ذریعے کی توثیق سے قبل، براہِ کرم یہ یقینی بنائیں کہ آپ شناختی توثیق کا عمل مکمل کرتے ہیں۔ آپ عمل کو مکمل کرنے کی خاطر شناختی توثیق کے ٹیب میں جا سکتے ہیں، اور مقامی تقاضوں کے پیشِ نظر مجاز پاسپورٹ یا کوئی بھی دیگر قابلِ قبول ID دستاویز اپلوڈ کر سکتے ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'ur-PK', 'معزز صارف، Binance نے اپنے تمام صارفی اکاؤنٹس کے لیے، یومیہ 2 ملین USD کی نئی فیاٹ حدود فراہم کی ہیں۔ اس لیے، آپ کی حد میں اضافے کی موجودہ درخواست (500k / 1 ملین/2 ملین USD کے لیے) کو غیر ضروری تصور کیا جاتا ہے۔ اپنی ٹریڈنگ سے لطف اندوز ہوں!', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'ur-PK', 'افسوس، ہم فراہم کردہ ثبوت کے ساتھ آپ کی درخواست کی توثیق کرنے کے قابل نہیں تھے۔ ہم آپ کی مزید معاونت کرنے کی خاطر، آپ کو اپنے تعمیلی شعبے کے ساتھ چیٹ کرنے کی دعوت دینا چاہیں گے۔ آپ کو چند منٹوں میں ایک دعوتی ای میل موصول ہو گی۔ براہِ کرم آگے بڑھنے کی خاطر، "ابھی چیٹ کریں" بٹن پر کلک کریں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'ur-PK', 'اپلوڈ کردہ دستاویزی ثبوت واضح نہیں ہے اور یہ ہمارے نظر آنے والے تقاضوں پر پورا نہیں اترتا۔ براہ کرم اصل دستاویز کو اپلوڈ کریں۔ ہم اس بات کو ترجیح دیتے ہیں کہ ہمیں یہ دستاویزات ڈیجیٹل .pdf یا مادی اسٹیٹمنٹس کی مکمل تصاویر کے طور پر موصول ہوں، جس میں دستاویز کے تمام چار کنارے نظر آ رہے ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'ur-PK', 'براہِ کرم ہمارا PEP کا اعلامیہ فارم درست جوابات کے ساتھ مکمل کریں۔ براہِ کرم ہمیں مطلع کریں کہ آیا آپ بطورِ PEP درجہ بند کیے گئے ہیں یا نہیں، آپ کا مکمل نام، پوزیشن، تعلق (اگر آپ بلحاظِ ایسوسی ایشن PEP ہیں)، اور آپ کتنے عرصے سے بطورِ PEP اپنی حیثیت برقرار رکھے ہوئے ہیں۔ آپ یہ معلومات فراہم کرنے کے بعد اپنی درخواست دوبارہ جمع کروا سکتے ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'ur-PK', 'دولت کا ذریعہ بھیجنے یا فنڈز کے ذریعے کی توثیق سے قبل، براہِ کرم یہ یقینی بنائیں کہ آپ پروف آف ایڈریس کا توثیقی عمل مکمل کرتے ہیں۔ آپ یہ عمل مکمل کرنے کی خاطر شناختی توثیق کے ٹیب میں جا سکتے ہیں اور ایک مجاز بینک اسٹیٹمنٹ/یوٹیلیٹی بل/ٹیکس دستاویز اپلوڈ کر سکتے ہیں، جو گزشتہ تین مہینوں میں جاری کی گئی ہو اور جس میں آپ کا نام اور ایک درست ایڈریس نظر آ رہا ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر الاؤنس کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) ایک بینک اسٹیٹمنٹ جو گزشتہ 3 مہینوں کے لیے الاؤنس ٹرانسفرز کو ظاہر کر رہی ہو؛ 2) ایک حکومتی اجراء کردہ الاؤنس یا دیگر سماجی فوائد کی اسٹیٹمنٹ۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'ur-PK', 'آپ نے یہ بتایا ہے کہ آپ کے فنڈز کے ذرائع اثاثہ جات کی فروخت سے ہیں۔ براہِ کرم ایک ایسی بینک اسٹیٹمنٹ فراہم کریں جو آپ کے اثاثہ جات کی فروخت سے حاصل ہونے والی ادائیگی آپ کے اکاؤنٹ میں ظاہر کر رہی ہو، اور جس میں آپ کا نام اور آپ کی جانب سے دی گئی درخواست کے 3 مہینوں کے اندر اجراء کی تاریخ واضح انداز میں موجود ہو۔ ہم اس بات کو ترجیح دیتے ہیں کہ ہمیں یہ دستاویزات ڈیجیٹل .pdf یا مادی اسٹیٹمنٹس کی مکمل تصاویر کے طور پر موصول ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'ur-PK', 'آپ نے بتایا ہے کہ آپ کے اکاؤنٹ میں موجود فنڈز کرپٹو کی مائننگ کی سرگرمیوں سے حاصل کیے گئے ہیں۔ اپنی درخواست کی معاونت کرنے کی خاطر، براہِ کرم یہ فراہم کریں: 1) مائننگ کے لیے استعمال ہونے والے ہارڈ ویئر کی خریداری کا ثبوت (جو آپ اور فروخت کنندہ دونوں کی تفصیلات کو ظاہر کر رہا ہو)؛ 2) متعلقہ پلیٹ فارم(پلیٹ فارمز)/ایکسچینج(ایکسچینجز) سے حاصل ہونے والی مائننگ کی تمام آمدنیوں کا ثبوت۔ ہمیں ہر مثال میں کم از کم 3 مہینوں کی ٹرانزیکشن ہسٹری کے اسکرین شاٹس درکار ہیں، جس میں مائن شدہ کوائنز کی تمام سرگرمی موجود ہو اور وہ والیٹ ایڈریسز اور ٹرانزیکشن IDs ڈسپلے کر رہے ہوں۔ انہیں لازمی طور پر متعلقہ پلیٹ فارم/ایکسچینج سے لینا چاہیئے اور ان میں آپ کے اکاؤنٹ کی تفصیلات شامل ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر ایک روزہ ٹریڈنگ کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں:1) ٹرانزیکشنز کی اسٹیٹمنٹس جو گزشتہ مہینے کی آپ کی ٹریڈنگ سرگرمی کو ظاہر کر رہی ہوں، اور ایک بینک اسٹیٹمنٹ جو آپ کے اکاؤنٹ میں ڈپازٹ شدہ منافع جات نکلوانے کو ظاہر کر رہی ہو۔ دونوں دستاویزات کو لازمی طور پر اکاؤںٹ رجسٹریشن کی تفصیلات اور اجرا کنندہ کا لوگو ظاہر کرنا چاہیئے؛ 2) گزشتہ ٹیکس سال کے لیے ایک ٹیکس اسٹیٹمنٹ، جو ٹریڈنگ کے منافع جات سے حاصل ہونے والی آپ کی آمدنی کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'ur-PK', 'آپ نے اپنے فنڈز کے بنیادی ذرائع کے طور پر کسی کمپنی کی جانب سے منافع جات کی ادائیگیوں/منافع کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) منافع جات کی اسٹیٹمنٹس؛ 2) تقسیم کے معاہدہ جات؛ 3) ایک بینک اسٹیٹمنٹ جو منافع جات کی ادائیگیوں کو ظاہر کر رہی ہو؛ 4) کمپنی اکاؤںٹس کا سب سے زیادہ تازہ ترین آڈٹ۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر عطیات کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) ریئل اسٹیٹ یا دیگر اثاثہ جات کے لیے عطیات کا معاہدہ؛ 2) عطیہ کنندہ کی جانب سے دستخط شدہ بیان حلفی/خط جو تحفے کی نوعیت بیان کر رہا ہو؛ 3) ایک بینک اسٹیٹمنٹ جو عطیے کے بینک ڈپازٹ کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر جوئے کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں:1) ٹرانزیکشنز کی اسٹیٹمنٹس جو گزشتہ مہینے کے لیے آپ کی جوئے کی سرگرمی کو ظاہر کر رہی ہو، اور ایک بینک اسٹیٹمنٹ جو آپ کے اکاؤنٹ میں ڈپازٹ شدہ منافع نکلوانے کو ظاہر کر رہی ہو۔ دونوں دستاویزات کو لازمی طور پر اکاؤںٹ رجسٹریشن کی تفصیلات اور اجرا کنندہ کا لوگو ظاہر کرنا چاہیئے؛ 2) گزشتہ ٹیکس سال کے لیے ایک ٹیکس اسٹیٹمنٹ، جو جوئے کے منافع جات سے حاصل ہونے والی آپ کی آمدنی کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'ur-PK', 'آپ نے فنڈز کے بنیادی ذریعے کے طور پر وراثت کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت ناکافی ہے اور یہ ہمارے تقاضا جات پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) وصیت نامے/بیانِ حلفی کی ایک نقل؛ 2) وصیت کے تعمیل کنندہ (وکیل/قانونی مختار/وصیت دہندہ) کی طرف سے ایک دستخط شدہ خط۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر قرضہ جات/مورگیجز کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: قرضے/مورگیج کا معاہدہ جو قرضے کی رقم اور دوبارہ ادائیگی کے منصوبے کو ظاہر کر رہا ہو، اور ایک بینک اسٹیٹمنٹ جو آپ کے اکاؤنٹ میں ہونے والے قرضہ جاتی/مورگیج ڈپازٹس کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر غیر فعال آمدنی کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) ایک دستخط شدہ کرائے/لیز کا معاہدہ اور درج ذیل میں سے ایک: a. بینک اسٹیٹمنٹ جو کرائے/لیز کی نئی ادائیگی کو ظاہر کر رہی ہو؛ b۔ کرائے/لیز کی سب سے تازہ ترین رسیدیں؛ 2) کوئی بھی دیگر دستاویزات جو گزشتہ مہینے کے لیے آپ کی غیر فعال آمدنی کو ثابت کر رہی ہوں (مثلاً۔ کتابی اعزازات، ملحقہ تشہیر، اسٹیکنگ وغیرہ)۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر پینشن کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) ایک بینک اسٹیٹمنٹ جو گزشتہ 3 مہینوں کے لیے پینشن ٹرانسفرز کو ظاہر کر رہی ہو؛ 2) ایک حکومتی اجراء کردہ پینشن کی اسٹیٹمنٹ؛ 3) پینشن فنڈ کی اسٹیٹمنٹس۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر تنخواہ کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) پے سلپس جو کم از کم گزشتہ مہینے سے آپ کی آمدنی کو ظاہر کر رہی ہوں؛ 2) ایک بینک اسٹیٹمنٹ جو کم از کم گزشتہ مہینے سے آپ کے آجر کی جانب سے تنخواہ کی ادائیگیوں کو ظاہر کر رہی ہو؛ 3) ایک ٹیکس اسٹیٹمنٹ جو گزشتہ ٹیکس کے سال پر مشتمل ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر مالیاتی اثاثہ جات کی فروخت کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) آپ کے سرمایہ کاری کے فراہم کنندہ کی جانب سے ایک اسٹیٹمنٹ؛ 2) ایک بینک اسٹیٹمنٹ جو آپ کے سرمایہ کاری کے فراہم کنندہ کی جانب سے تصفیہ جات کو ڈسپلے کر رہی ہو؛ 3) دیگر اسٹیٹمنٹس یا دستاویزات جو بانڈز، اسٹاکس وغیرہ سے سرمایہ کاری کے منافع کو ثابت کر رہی ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر ریئل اسٹیٹ یا دیگر اثاثہ جات کی فروخت کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) فروخت/تصفیے کی اسٹیٹمنٹ کا ایک معاہدہ؛ 2) قانونی مختار/وکیل/اسٹیٹ ایجنٹ کی جانب سے ایک دستخط شدہ خط جو جائیداد کی فروخت کی تصدیق کر رہا ہو؛ 3) زمین کی رجسٹری/وقف نامے کی نقول۔ علاوہ ازیں، آپ ہمیں ایک ایسی بینک اسٹیٹمنٹ بھیج سکتے ہیں، جو آپ کے بینک اکاؤنٹ میں فروخت کے فنڈز کے ڈپازٹ کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'ur-PK', 'آپ نے فنڈز کے اپنے بنیادی ذرائع کے طور پر سیونگز کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم ہمیں کسی سیونگز اکاؤںٹ سے (گزشتہ 3 مہینوں میں جاری ہوئی تھی) اسٹیٹمنٹ بھیجیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'ur-PK', 'آپ نے اپنے فنڈز کے بنیادی ذرائع کے طور پر آزاد پیشے کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم ہمیں گزشتہ ٹیکس سال پر مشتمل ایک ٹیکس اسٹیٹمنٹ بھیجیں۔ اضافی طور پر، آپ ہمیں آزاد پیشے کی سروسز کے لیے تازہ ترین انوائسز/معاہدے/معاہدہ جات، یا منافع/خسارے کی اسٹیٹمنٹس بھیج سکتے ہیں، جو آپ کی ماہانہ یا سالانہ آمدنی کو ثابت کر رہی ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر کمپنی منافع جات (شیئرز/منافع جات) کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) منافع جات کی اسٹیٹمنٹس؛ 2) تقسیم کے معاہدہ جات؛ 3) ایک بینک اسٹیٹمنٹ جو منافع جات کی ادائیگیوں کو ظاہر کر رہی ہو؛ 4) کمپنی اکاؤںٹس کا سب سے زیادہ تازہ ترین آڈٹ۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'ur-PK', 'کرپٹو سرمایہ کاری کی توثیق کریں: آپ کی دولت کے بنیادی ذریعے کے طور پر کرپٹو کے لیے آپ کے فراہم کردہ ثبوت ناکافی ہیں۔ دیگر ایکسچینجز کی اسٹیٹمنٹس، کولڈ والیٹس کے اسکرین شاٹس، کرپٹو خریداری کی رسیدیں، یا کوئی بھی متعلقہ دستاویزات جمع کرواتے ہوئے اضافی توثیق فراہم کریں۔ اس بات کو یقینی بنائیں کہ فراہم کردہ ثبوت ہمارے سسٹم پر آپ کے اعلامیے سے مماثلت رکھتا ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر عطیے کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) ریئل اسٹیٹ یا دیگر اثاثہ جات کے لیے عطیات کا معاہدہ؛ 2) عطیہ کنندہ کی جانب سے دستخط شدہ بیان حلفی/خط جو تحفے کی نوعیت بیان کر رہا ہو؛ 3) ایک بینک اسٹیٹمنٹ جو عطیے کے بینک ڈپازٹ کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر مالیاتی سرمایہ کاری کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) آپ کے سرمایہ کاری کے فراہم کنندہ کی جانب سے ایک اسٹیٹمنٹ؛ 2) ایک بینک اسٹیٹمنٹ جو آپ کے سرمایہ کاری کے فراہم کنندہ کی جانب سے تصفیہ جات کو ڈسپلے کر رہی ہو؛ 3) دیگر اسٹیٹمنٹس یا دستاویزات جو بانڈز، اسٹاکس وغیرہ سے سرمایہ کاری کے منافع کو ثابت کر رہی ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر وراثت کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) وصیت نامے/بیانِ حلفی کی ایک نقل؛ 2) وصیت کے تعمیل کنندہ (وکیل/قانونی مختار/وصیت دہندہ) کی جانب سے ایک دستخط شدہ خط۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر مورگیجز/قرضہ جات کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل فراہم کریں: قرضے/مورگیج کا معاہدہ جو قرضے یا مورگیج کی مالیت اور دوبارہ ادائیگی کے منصوبے کو ظاہر کر رہا ہو، اور ایک بینک اسٹیٹمنٹ جو آپ کے اکاؤنٹ میں ہونے والے قرضہ جاتی/مورگیج ڈپازٹ کو ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر تنخواہ کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اپنی توثیق کو مکمل کرنے کی غرض سے ہمیں درج ذیل میں سے ایک یا اس سے زائد فراہم کریں: 1) پے سلپس جو کم از کم گزشتہ مہینے سے آپ کی آمدنی کو ظاہر کر رہی ہوں؛ 2) ایک بینک اسٹیٹمنٹ جو کم از کم گزشتہ مہینے سے آپ کے آجر کی جانب سے تنخواہ کی ادائیگیوں کو ظاہر کر رہی ہو؛ 3) ایک ٹیکس اسٹیٹمنٹ جو گزشتہ ٹیکس کے سال پر مشتمل ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'ur-PK', 'آپ نے دولت کے اپنے بنیادی ذرائع کے طور پر آزاد پیشے کا انتخاب کیا ہے، تاہم فراہم کردہ دستاویزی ثبوت کافی نہیں ہے اور یہ ہمارے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم ہمیں گزشتہ ٹیکس سال پر مشتمل ایک ٹیکس اسٹیٹمنٹ بھیجیں۔ اضافی طور پر، آپ ہمیں آزاد پیشے کی سروسز کے لیے تازہ ترین انوائسز/معاہدے/معاہدہ جات، یا منافع/خسارے کی اسٹیٹمنٹس بھیج سکتے ہیں، جو آپ کی ماہانہ یا سالانہ آمدنی کو ثابت کر رہی ہوں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'ur-PK', 'ہم نے آپ کی مجموعی دولت کے اعلامیے میں تضاد کی شناخت کی ہے۔ فراہم کردہ دستاویزی ثبوت نمایاں طور پر کُل اثاثہ جات کی ایک زائد مالیت کو ظاہر کرتا ہے، اور آپ نے جو مالیت Binance کے ساتھ بیان کی ہے یہ اُس کے ساتھ مطابقت نہیں رکھتا۔ براہِ کرم آپ ہمیں اپنی زیرِ ملکیت موجود تمام اثاثہ جات کی کُل مجموعی (اندازاً) مالیت کے متعلق درست معلومات فراہم کریں اور اپنی درخواست دوبارہ جمع کروائیں۔ غلط، ناکافی، یا گمراہ کُن معلومات فراہم کرنے سے آپ کی درخواست کی فوری منظوری نہیں ہوتی۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'ur-PK', 'آپ کے اعلامیے کا جائزہ لینے کے بعد، ہمیں واضح نقائص ملے ہیں۔ تیز رفتار عمل کو یقینی بنانے کے لیے، اپنی سالانہ آمدنی (مجموعی)، کل اثاثہ جات اور دولت کے ذرائع کا درست اور مکمل ڈیٹا فراہم کریں۔ براہِ کرم اپنے اعلامیے کے ساتھ مناسب ثبوت بھی جمع کروائیں۔ نادرست یا ناکافی معلومات آپ کی درخواست میں تاخیر کا سبب بنیں گی۔ آپ کے تعاون کا شکریہ۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'ur-PK', 'ہم نے آپ کی ملازمت کی تفصیلات کے اعلامیے میں غلط، غیر مماثل، یا نامکمل معلومات کی شناخت کی ہے۔ براہِ کرم درست معلومات کے ہمراہ اپنی درخواست دوبارہ جمع کروائیں، بشمول: 1) ملازمت کا اسٹیٹس - موجودہ برسرِ روزگار/آزاد پیشہ/طالب علم/ریٹائرڈ/دیگر اسٹیٹس؛ 2) آجر/کاروبار کا نام - آپ کے آجر کی کمپنی کا نام/کاروبار کا نام؛ 3) آجر/کاروبار کا ایڈریس - رجسٹر کردہ آجر/کاروبار کا ایڈریس۔ براہِ کرم اس بات کو یقینی بنائیں کہ فراہم کردہ معلومات تازہ ترین ہیں اور یہ آپ کے دستاویزی ثبوت میں فراہم کردہ معلومات کے ساتھ مماثل ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'ur-PK', 'ہم نے آپ کے کسی دیگر بینک اکاؤںٹ سے فنڈز کی ٹرانسفر کو ملاحظہ کیا ہے۔ براہِ کرم ہمیں گزشتہ 3 مہینوں میں اجراء کردہ بینک اسٹیٹمنٹ بھیجیں، جو دیگر اکاؤںٹ کی ٹرانزیکشن ہسٹری (کم از کم 1 مہینے کی ٹرانزیکشنز) ظاہر کر رہی ہو۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'ur-PK', 'آپ کی تصویر کا تصویری معیار واضح نہیں ہے اور یہ ہمارے نظر آنے والے تقاضوں پر پورا نہیں اترتا۔ براہِ کرم اعلیٰ ریزولوشن (کم از کم 300 DPI) کی حامل نقل دوبارہ جمع کروایں، جو فریم میں تمام چار کناروں کے ساتھ مکمل صفحے کو ظاہر کر رہی ہو۔ اس کے برعکس، آپ اپنی توثیق کو مکمل کرنے کی خاطر مختلف دستاویزات فراہم کر سکتے ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADDITIONAL_DOCUMENT_REQUIRED', 'ur-PK', 'پڑتال مکمل کرنے کے لیے اضافی دستاویزات کی ضرورت ہے۔
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'ur-PK', 'توثیق ناکام رہی۔ یہ سکیورٹی کی وجوہات کے باعث یا پھر آپ کے ملک/خطے میں عائد پابندیوں کے باعث ہو سکتا ہے۔ ہم کسی بھی قسم کی زحمت کے لیے معذرت خواہ ہیں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'ur-PK', 'ہم معذرت چاہتے ہیں، ہم آپ کی پروفائل کی توثیق نہیں کر سکے کیونکہ آپ کی عمر تقاضا جات پر پوری نہیں اترتی۔ اگر آپ کی تاریخ پیدائش(عمر) تقاضے پر پوری اترتی ہے، تو براہِ کرم ایک واضح تصویر لیں اور دوبارہ سے کوشش کریں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BACK_SIDE_MISSING', 'ur-PK', 'دستاویز کا عقبی حصہ غائب ہے۔
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_AVATAR', 'ur-PK', 'براہ کرم لاگ ان کے صفحے پر واپس جائیں اور ID کی توثیق دوبارہ کرنے کی کوشش کریں۔', '2023-06-18 18:48:50', '2023-06-18 18:48:50') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_FACE_MATCHING', 'ur-PK', 'دستاویز اور سیلفی کے درمیان پڑتال کے بعد چہرے کی عدم مماثلت سامنے آئی۔
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_PROOF_OF_ADDRESS', 'ur-PK', 'ایڈریس کا غلط ثبوت اپلوڈ کیا گیا۔
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_BAD_PROOF_OF_IDENTITY', 'ur-PK', 'ID کی دستاویز کا غلط ثبوت اپلوڈ کیا گیا۔
