INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_PROBLEMATIC_APPLICANT_DATA', 'vi-VN', 'Vui lòng cung cấp họ tên/ngày sinh/địa chỉ ghi trên giấy tờ.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_REGULATIONS_VIOLATIONS', 'vi-VN', 'Xác minh không thành công. Điều này có thể do lý do an ninh hoặc quốc gia/khu vực của bạn bị hạn chế. Chúng tôi xin lỗi nếu có điều bất tiện xảy ra.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_REQUESTED_DATA_MISMATCH', 'vi-VN', 'Thông tin đã cung cấp không khớp với thông tin được nhận từ dữ liệu trên giấy tờ.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SANCTIONS', 'vi-VN', 'Xác minh không thành công. Điều này có thể do lý do an ninh hoặc quốc gia/khu vực của bạn bị hạn chế. Chúng tôi xin lỗi nếu có điều bất tiện xảy ra.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SCREENSHOTS', 'vi-VN', 'Ảnh chụp màn hình không được chấp nhận.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SELFIE_MISMATCH', 'vi-VN', 'Ảnh selfie không khớp với ảnh trên giấy tờ tùy thân.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
