INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_SPAM', 'vi-VN', 'Giấy tờ đã cung cấp không chính xác.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNFILLED_ID', 'vi-VN', 'Giấy tờ đã tải lên không có chữ ký và con dấu.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'vi-VN', 'Giấy tờ không đủ điều kiện. Các trường bắt buộc của giấy tờ không đọc được hoặc không nhìn thấy được. Vui lòng tải ảnh mới lên. Đảm bảo ảnh sáng, rõ ràng và tất cả các góc của giấy tờ đều nhìn được.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_ADDRESS', 'vi-VN', 'Địa chỉ trên giấy tờ không khớp với địa chỉ mà người dùng đã nhập.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'vi-VN', 'Rất tiếc, khu vực này không được hỗ trợ.', '2023-06-18 18:48:51', '2023-06-18 18:48:51') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'nl-NL', 'Verifieer inkomen: Verstrek bewijsstukken voor alle inkomstenbronnen die bij Binance zijn opgegeven, inclusief salaris, inkomsten als zelfstandige, pensioen, dividenden, handel, huur of andere inkomsten. Dien voldoende en correcte bewijsstukken in die overeenkomen met je opgegeven inkomen. Onjuiste of onvoldoende informatie zorgt voor vertraging bij de goedkeuring.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'nl-NL', 'Verstrek een recent bankafschrift (uitgegeven in de afgelopen 3 maanden). De volgende gegevens moeten erop staan: De naam of het logo van de uitgever en je transactiegeschiedenis, waarbij de maandelijkse transacties van je werkgever, je inkomen uit eigen onderneming, pensioenuitkering, toeslagen, dividenden, uitbetalingen van handels- of gokwinsten, huurinkomen of andere transacties die op regelmatige basis inkomen opleveren duidelijk zichtbaar moeten zijn en samen het volledige jaarinkomen vormen dat je bij Binance hebt aangegeven. Het heeft onze voorkeur als deze documenten digitaal in .pdf zijn of als volledige fotos van fysieke documenten.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'nl-NL', 'De geüploade bewijsdocumenten laten de uitgiftedatum niet duidelijk zien en kunnen niet worden geaccepteerd.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'nl-NL', 'Je hebt documenten geüpload waarop de persoonsgegevens niet zichtbaar zijn. Zorg ervoor dat je volledige naam, de uitgiftedatum en de logos van de uitgever zichtbaar zijn op de ondersteunende documentatie.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'nl-NL', 'Je bewijsdocumenten (met namen van derden) kunnen niet worden geaccepteerd als bewijsdocumenten voor de herkomst van je inkomen of van je vermogen. Upload documenten die uitgegeven zijn met je eigen naam of geef een verklaring hoe de documenten van derden gebruikt kunnen worden om je fiatactiviteiten of je totale nettovermogen te verifiëren.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'nl-NL', 'Beste Binancian, je aanmelding is goedgekeurd. Veel succes bij het beleggen bij Binance!', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'nl-NL', 'Zorg ervoor dat je het verificatieproces voltooit voordat je de verificatie van de bron van je vermogen of de bron van je inkomsten verstrekt. Je kunt het proces voltooien door naar Identiteitsverificatie te gaan en een geldig paspoort of ander acceptabel identiteitsbewijs te uploaden, afhankelijk van de lokale vereisten.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'nl-NL', 'Beste gebruiker, Binance biedt nu nieuwe fiatlimieten van 2 miljoen USD per dag voor al onze gebruikersaccounts. Je huidige aanvraag voor een hogere limiet (voor 500.000/1 miljoen/2 miljoen) wordt daarmee als onnodig beschouwd. Succes bij het handelen!', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'nl-NL', 'Helaas waren we niet in staat om je aanmelding te verifiëren met het verstrekte bewijs. Om je verder te kunnen begeleiden, willen we je uitnodigen voor een gesprek met onze compliance-afdeling. Je krijgt over een paar minuten een uitnodigingsmail. Klik op Nu chatten om verder te gaan.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'nl-NL', 'De geüploade bewijsdocumenten zijn niet duidelijk genoeg en voldoen niet aan de leesbaarheidseisen. Upload het originele document. Het heeft onze voorkeur als deze documenten digitaal in .pdf zijn of volledige fotos van de fysieke verklaringen waarop alle vier de hoeken van het document zichtbaar zijn.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'nl-NL', 'Vul ons PEP-verklaringsformulier in met nauwkeurige antwoorden. Vertel ons of je wel of niet als een PEP bent geclassificeerd, je volledige naam, functie, relatie (als je gerelateerd bent aan een PEP), en hoe lang je al PEP bent. Na het verstrekken van deze gegevens kun je je aanmelding opnieuw indienen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'nl-NL', 'Zorg ervoor dat je de verificatie van het bewijs van je adres voltooit voordat je de verificatie van de herkomst van je vermogen of van je inkomsten verstrekt. Je kunt dit proces voltooien door naar Identiteitsverificatie te gaan en een geldig(e) bankafschrift/nutsrekening/belastingdocument te uploaden dat in de afgelopen drie maanden is uitgegeven, op jouw naam staat en duidelijk een nauwkeurig adres vermeldt.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'nl-NL', 'Je hebt toeslagen gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een bankafschrift waarop overschrijving van toeslagen voor de laatste 3 maanden staan vermeld; 2) Een door de overheid uitgegeven verklaring van toeslagen of andere verklaringen van sociale uitkeringen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'nl-NL', 'Je hebt de verkoop van activa ingevuld als je belangrijkste inkomstenbron. Verstrek een bankafschrift waarop de betaling op je bankrekening van de verkoop van je activa staat vermeld, met duidelijke vermelding van je naam en een uitgiftedatum in de afgelopen 3 maanden sinds je aanmelding. Het heeft onze voorkeur als deze documenten digitaal in .pdf zijn of als volledige fotos van fysieke documenten.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'nl-NL', 'Je hebt verklaard dat het vermogen op je account afkomstig is vanuit cryptominingactiviteiten. Om je aanmelding te ondersteunen, moet je een van de volgende documenten verstrekken: 1) Bewijs van de aankoop van de hardware die voor mining wordt gebruikt (waarop zowel jouw gegevens als die van de verkoper worden vermeld); 2) Bewijs van alle winsten uit cryptomining van relevante platforms en beurzen. In ieder geval vereisen we een screenshot voor minimaal 3 maanden aan transactiegeschiedenis, waarbij alle activiteiten met geminede munten, walletadressen en transactie-IDs worden weergegeven. Deze moeten genomen worden op het relevante platform of de relevante beurs en je accountgegevens bevatten.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'nl-NL', 'Je hebt daghandel gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Transactieoverzichten die je handelsactiviteiten van de afgelopen maand bewijzen EN een bankafschrift waarop de stortingen van de winstuitkeringen op je rekening staan vermeld. Beide documenten moeten je rekening- of accountgegevens vermelden en het logo van de uitgever; 2) Een belastingaangifte van het afgelopen belastingjaar die je inkomen uit handelswinsten bewijst.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'nl-NL', 'Je hebt dividendbetalingen/winst uit onderneming gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Dividendverklaringen; 2) Winstdelingsregelingen; 3) Een bankafschrift waarop de dividendbetalingen staan vermeld; 4) De meest recente gecontroleerde bedrijfsrekeningen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'nl-NL', 'Je hebt schenkingen gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een schenkingsovereenkomst van vastgoed of andere activa; 2) Een ondertekende verklaring of brief van de schenker waarin de aard van de schenking wordt verklaard; 3) Een bankafschrift waarop de storting van de schenking wordt vermeld.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'nl-NL', 'Je hebt gokken gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Transactieoverzichten die je gokactiviteiten van de afgelopen maand bewijzen EN een bankafschrift waarop de stortingen van de winstuitkeringen op je rekening staan vermeld. Beide documenten moeten je rekening- of accountgegevens vermelden en het logo van de uitgever; 2) Een belastingaangifte van het afgelopen belastingjaar, waarmee je inkomen uit gokwinsten bewijst.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'nl-NL', 'Je hebt erfenis gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een kopie van een wilsbeschikking/testament; 2) Een ondertekende brief van de executeur van het testament (advocaat/advocaat/persoon die het testament toekent).', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'nl-NL', 'Je hebt leningen/hypotheken gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons de volgende documenten om je verificatie te voltooien: Een leen-/hypotheekcontract dat het leenbedrag en aflossingsschema vermeldt EN een bankafschrift dat de stortingen voor de aflossing van de lening/hypotheek op je rekening vermeldt.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'nl-NL', 'Je hebt passief inkomen gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een ondertekende huur-/leaseovereenkomst EN een van de volgende: a. Een bankafschrift waar de laatste huur-/leasebetaling op staat, b. De meest recente huur-/leaserekeningen; 2) Alle andere documenten die je passieve inkomen bewijzen (zoals opbrengsten uit boekenverkoop, affiliate marketing, staking enz.) voor de afgelopen maand.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'nl-NL', 'Je hebt pensioen gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een bankafschrift waarop de overschrijving van je pensioenuitkering voor de laatste 3 maanden staat vermeld; 2) Een door de overheid uitgegeven pensioenverklaring; 3) Verklaring van een pensioenfonds.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'nl-NL', 'Je hebt salaris gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een loonstrook waarop je inkomen van de afgelopen maand staat; 2) Een bankafschrift waarop je salarisbetalingen van je werkgever van minimaal een maand vermeld staan; 3) Een belastingaangifte van het afgelopen belastingjaar.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'nl-NL', 'Je hebt verkoop van financiële activa gekozen als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een verklaring van je beleggingsaanbieder; 2) Een bankafschrift waarop de betalingen van je beleggingsaanbieder worden weergegeven; 3) Andere verklaringen of documenten die de beleggingswinst vanuit obligaties, aandelen, enz. bewijzen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'nl-NL', 'Je hebt de verkoop van vastgoed of andere activa ingevuld als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een verkoopcontract/afwikkelingsverklaring; 2) Een ondertekende verklaring van een notaris/advocaat/makelaar die de vastgoedverkoop bevestigt; 3) Kopiën van de registratie/eigendomsakte van land. Daarnaast kun je ons ook een bankafschrift sturen waaruit blijkt dat het geld van de verkoop op je bankrekening is gestort.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'nl-NL', 'Je hebt spaartegoeden gekozen als je inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een afschrift van je spaarrekening (uitgegeven in de afgelopen 3 maanden).', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'nl-NL', 'Je hebt zelfstandig ondernemerschap ingevuld als je belangrijkste inkomstenbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een belastingaangifte van het afgelopen belastingjaar. Daarnaast kun je ons recente facturen/contracten/overeenkomsten verstrekken voor de diensten die je als zelfstandige aanbiedt of winst en verliesrekeningen die je maandelijkse of jaarlijkse inkomen bewijzen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'nl-NL', 'Je hebt bedrijfswinsten (aandelen/dividenden) gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Dividendverklaringen; 2) Winstdelingsregelingen; 3) Een bankafschrift waarop de dividendbetalingen staan vermeld; 4) De meest recente gecontroleerde bedrijfsrekeningen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'nl-NL', 'Verifieer crypto-investering: Het verstrekte bewijs voor crypto als je belangrijkste inkomstenbron is onvoldoende. Zorg voor aanvullende verificatie door documenten van andere beurzen, screenshots van cold wallets, crypto-aankoopbewijzen of andere relevante documenten in te dienen. Zorg ervoor dat het aangeleverde bewijs overeenkomt met je aangifte in ons systeem.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'nl-NL', 'Je hebt schenkingen gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een schenkingsovereenkomst van vastgoed of andere activa; 2) Een ondertekende verklaring of brief van de schenker waarin de aard van de schenking wordt verklaard; 3) Een bankafschrift waarop de storting van de schenking wordt vermeld.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'nl-NL', 'Je hebt financiële beleggingen gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een verklaring van je beleggingsaanbieder; 2) Een bankafschrift waarop de betalingen van je beleggingsaanbieder worden weergegeven; 3) Andere verklaringen of documenten die de beleggingswinst vanuit obligaties, aandelen, enz. bewijzen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'nl-NL', 'Je hebt erfenis gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een kopie van een wilsbeschikking/testament; 2) Een ondertekende brief van de executeur van het testament (advocaat/notaris/toekenning van nalatenschappen).', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'nl-NL', 'Je hebt hypotheken/leningen gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons de volgende documenten om je verificatie te voltooien: Een hypotheek-/leencontract dat de waarde van de hypotheek of lening en het aflossingsschema vermeldt EN een bankafschrift dat de storting voor de aflossing van de lening/hypotheek op je rekening vermeldt.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'nl-NL', 'Je hebt salaris gekozen als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een of meer van de volgende documenten om je verificatie te voltooien: 1) Een loonstrook waarop je inkomen van de afgelopen maand staat; 2) Een bankafschrift waarop je salarisbetalingen van je werkgever van minimaal een maand vermeld staan; 3) Een belastingaangifte van het afgelopen belastingjaar.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'nl-NL', 'Je hebt zelfstandig ondernemerschap ingevuld als je belangrijkste vermogensbron, maar de verstrekte bewijsdocumenten zijn onvoldoende en voldoen niet aan onze eisen. Stuur ons een belastingaangifte van het afgelopen belastingjaar. Daarnaast kun je ons recente facturen/contracten/overeenkomsten verstrekken voor de diensten die je als zelfstandige aanbiedt of winst en verliesrekeningen die je maandelijkse of jaarlijkse inkomen bewijzen.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'nl-NL', 'We hebben een discrepantie opgemerkt in de verklaring van je totale vermogen. De bewijsdocumenten geven een significant hogere waarde aan totaal vermogen weer en dat komt niet overeen met wat je bij Binance hebt opgegeven. Verstrek ons nauwkeurige gegevens over de totale (geschatte) waarde van alle activa die in je bezit zijn en stuur je aanmelding opnieuw in. Het opgeven van onjuiste, onvoldoende of misleidende gegevens zorgt voor vertraging in de goedkeuring van je aanmelding.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'nl-NL', 'Na controle bleek je aangifte significante fouten te bevatten. Om een snelle afhandeling te garanderen, dien je correcte en volledige gegevens over je (bruto) jaarinkomen, totale activa en inkomstenbronnen te verschaffen. Stuur voldoende bewijsmateriaal met je aangifte mee. Onjuiste of onvoldoende informatie zorgt voor vertraging van je aanmelding. Bedankt voor je medewerking.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'nl-NL', 'We hebben onjuiste, onvolledige of discrepanties in gegevens op de aangifte van je werkgelegenheidsgegevens opgemerkt. Stuur de aanmelding opnieuw in met nauwkeurige gegevens, inclusief: 1) Werksituatie (huidige status als werknemer/zelfstandige/student/gepensioneerd/overig); 2) Naam van je werkgever/bedrijf (de naam van het bedrijf waar je in dienst bent of je eigen bedrijf); 3) Adres van je werkgever/bedrijf (het geregistreerde adres van je werkgever of eigen bedrijf). Zorg ervoor dat de gegevens up-to-date zijn en dat ze overeenkomen met de gegevens die je hebt opgegeven in je bewijsdocumenten.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'nl-NL', 'We hebben de overschrijving van vermogen vanaf je andere bankrekening opgemerkt. Stuur ons een bankafschrift dat in de afgelopen 3 maanden is uitgegeven, waarop de transactiegeschiedenis van de andere rekening staat (met minimaal 1 maand aan transacties).', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'nl-NL', 'De kwaliteit van je foto is niet duidelijk genoeg en voldoet niet aan onze leesbaarheidseisen. Stuur opnieuw een kopie in met een hogere resolutie (minimaal 300 dpi) waarop de volledige pagina met alle vier de hoeken in beeld zichtbaar zijn. Je kunt ook andere documenten verstrekken om je verificatie te voltooien.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADDITIONAL_DOCUMENT_REQUIRED', 'nl-NL', 'Aanvullende documenten nodig om door de controle te komen.
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_ADVERSE_MEDIA', 'nl-NL', 'Verificatie mislukt. Dit kan het gevolg zijn van veiligheidsredenen of van beperkingen in jouw land/regio. Onze excuses voor het ongemak.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_AGE_REQUIREMENT_MISMATCH', 'nl-NL', 'Sorry, we konden je profiel niet verifiëren omdat je leeftijd niet overeenkomt met de vereisten. Als je verjaardag (leeftijd) aan de vereisten voldoet, neem dan een duidelijke foto en probeer het opnieuw.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
