INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_DOCUMENT_PAGE_MISSING', 'nl-NL', 'Upload een foto van je document geopend op de pagina met biometrische gegevens, met je foto en persoonsgegevens.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
