INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_DUPLICATE', 'nl-NL', 'Er bestaat al een account met deze gebruikersgegevens. Dubbele accounts zijn niet toegestaan.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
