INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'nl-NL', 'Ongeschikte documenten. De verplichte velden van het document zijn niet leesbaar of zichtbaar. Upload een nieuwe foto. Zorg ervoor dat de foto helder en duidelijk is en dat alle hoeken van het document zichtbaar zijn.', '2023-06-18 18:48:52', '2023-06-18 18:48:52') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
