INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_UNSATISFACTORY_PHOTOS', 'cn', '证件不合格。证件的必填字段不可读或不可见。请上传一张新照片。确保照片明亮清晰，且证件的四个边角全部显示在照片中。', '2023-06-18 18:48:53', '2023-06-18 18:48:53') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
