INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('SUMSUB_SDK_WRONG_USER_REGION', 'cn', '抱歉，不支持该区域。', '2023-06-18 18:48:53', '2023-06-18 18:48:53') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual Income', 'en', 'Verify Income: Provide documentary evidence for all income sources declared with Binance, including salary, self-employment, pension, dividends, trading, rent, or other income. Submit sufficient and accurate supporting documents matching your declared income. Incorrect or insufficient information delays approval.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Annual income - Bank Statement', 'en', 'Please provide a recent bank statement (issued within the last 3 months). It must contain your name, the issuer name/logo, and your transaction history, clearly showing monthly transfers from your employer, self-employed services, pension, allowances, dividends, trading or gambling profit withdrawals, rent or, any other transfers received on a regular basis that convey your full annual income declared with Binance. We prefer to receive these documents as a digital .pdf or full photos of physical statements.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Dates', 'en', 'The uploaded documentary evidence does not clearly show an issuing date and cannot be accepted.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Document With Missing Details', 'en', 'You have uploaded documents where your personal details are not visible. Please ensure your full name, the date of issue, and any issuer logos are displayed on the supporting documentation.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Documents Issued With Third-Party Names', 'en', 'Your documentary evidence (issued with third-party names) cannot be accepted as your Source of Wealth or Source of Funds verification documentation. Please upload documents issued with your personal name or provide clarification on how the third-party documents can be used to verify your fiat activity or total asset worth.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) EDD Approved', 'en', 'Dear Binancian, your application has been approved. Enjoy investing with Binance!', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) KYC Failed', 'en', 'Before sending a Source of Wealth or a Source of Funds verification, please make sure you complete the identity verification process. You can complete the process by going to the identity verification tab and by uploading a valid passport or any other acceptable ID document, depending on the local requirements.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Limits Already Increased', 'en', 'Dear User, Binance has provided new fiat limits of 2 million USD per day for all of our user accounts. Your current limit increase request (for 500k/1 mil/2 mil USD) is deemed, therefore, unnecessary. Enjoy your trading!', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Opening Chat', 'en', 'Unfortunately, we were not able to verify your application with the provided evidence. In order to further assist you, we would like to invite you to a chat with our compliance department. In a few minutes you will receive an invitation email. Please click the “Chat Now” button to proceed.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Original Copy Instead of a Screenshot', 'en', 'The uploaded documentary evidence is not clear enough and does not meet our visibility requirements. Please upload the original document. We prefer to receive these documents as a digital .pdf or full photos of physical statements with all four corners of the document visible.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) PEP Declaration - Incorrect/Incomplete', 'en', 'Please complete our PEP Declaration form with accurate responses. Please let us know if you are classified as a PEP or not, your full name, position, relationship (if you are a PEP by association), and for how long you have been a PEP. After providing this information, you can resubmit your application.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) POA Failed', 'en', 'Before sending a Source of Wealth or a Source of Funds verification, please make sure you complete the Proof of Address verification process. You can complete this process by going to the identity verification tab and by uploading a valid bank statement/utility bill/tax document, issued in the last three months, in your name, and with an accurate address visible.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Allowance', 'en', 'You have selected Allowance as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A bank statement showing allowance transfers for the last 3 months; 2) A government-issued allowance or other social benefits statement.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Bank Statement Sale of Financial/Real Estate Asset', 'en', 'You have declared that your source to funds is from the Sale of assets. Please provide a bank statement, showing the received payment into your bank account from the sale of your assets, with your name clearly shown and issuance date within 3 months of your application. We prefer to receive these documents as a digital .pdf or full photos of physical statements.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Crypto Mining', 'en', 'You have declared that the funds in your account are derived from crypto mining activities. In order to support your application, please provide either: 1) Proof of purchase for the hardware used for mining (showing both yours and the sellers details); 2) Proof of all mining revenues from relevant platform(s)/exchange(s). In each case, we require screenshots for at least 3 months transaction history, detailing all activity with mined coins and displaying wallet addresses and transaction IDs. These must be taken from the relevant platform/exchange and include your account details.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Day Trading', 'en', 'You have selected Day trading as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification:1) Transactions statements, proving your trading activity for the last month AND a bank statement, showing profit withdrawals deposited in your account. Both documents must show account registration details and the issuer logo; 2) A tax statement for the previous tax year, proving your income from trading profits.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Dividends Payments/Profit From a Company', 'en', 'You have selected Dividends payments/Profit from a company as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Dividend statements; 2) Distribution agreements; 3) A bank statement showing dividend payments; 4) The most recent audit of company accounts.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Donations', 'en', 'You have selected Donations as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A donation agreement for real estate or other assets; 2) A signed affidavit/letter from the donor declaring the nature of the gift; 3) A bank statement showing a bank deposit of the donation.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Gambling', 'en', 'You have selected Gambling as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification:1) Transactions statements, proving your gambling activity for the last month AND a bank statement, showing profit withdrawals deposited in your account. Both documents must show account registration details and the issuer logo; 2) A tax statement for the previous tax year, proving your income from gambling profits.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Inheritance', 'en', 'You have selected Inheritance as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A copy of a will/testament; 2) A signed letter from the executor of the will (lawyer/solicitor/person given grant of probate).', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Loans/Mortgages', 'en', 'You have selected Loans/Mortgages as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send the following to complete your verification: A Loan/mortgage contract, showing the loan amount and repayment plan AND a bank statement showing loan/mortgage deposits into your account.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Passive Income', 'en', 'You have selected Passive income as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A signed rental/lease agreement AND one of the following: a. A bank statement, showing the latest rental/lease payment; b. The most recent rent/lease receipts; 2) Any other documents that prove your passive income (e.g. book royalties, affiliate marketing, staking etc.) for the last month.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Pension', 'en', 'You have selected Pension as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A bank statement showing pension transfers for the last 3 months; 2) A government-issued pension statement; 3) Pension fund statements.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Salary', 'en', 'You have selected Salary as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Payslips showing your income from at least the last month; 2) A bank statement showing salary payments from your employer for at least the last month; 3) A tax statement from the previous tax year.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Financial Assets', 'en', 'You have selected Sale of Financial assets as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A statement from your investment provider; 2) A bank statement displaying settlements from your investment provider; 3) Other statements or documents, proving investment profit from bonds, stocks, etc.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Sale of Real Estate or Other Assets', 'en', 'You have selected Sale of Real estate or other assets as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A contract of sale/settlement statement; 2) A signed letter from a solicitor/lawyer/estate agent confirming the property sale; 3) Land registry/title deed copies. Additionally, you can send us a bank statement, showing the deposit of sale funds into your bank account.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Savings', 'en', 'You have selected Savings as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a statement from a savings account (issued in the last 3 months).', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOF - Self-Employment', 'en', 'You have selected Self-employment as your main Source of Funds, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a tax statement from the previous tax year. Additionally, you can send us recent invoices/contracts/agreements for self-employed services or profit/loss statements, proving your monthly or annual income.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Company Profits (Shares/Dividends)', 'en', 'You have selected Company profits (shares/dividends) as your Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Dividend statements; 2) Distribution agreements; 3) A bank statement showing dividend payments; 4) The most recent audit of company accounts.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Crypto Investment', 'en', 'Verify Crypto Investment: Your provided evidence for Crypto as your main source of wealth is insufficient. Provide additional verification by submitting statements from other exchanges, screenshots of cold wallets, crypto purchase receipts, or any relevant documents. Ensure the provided evidence matches your declaration on our system.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Donation', 'en', 'You have selected Donation as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A donation agreement for real estate or other assets; 2) A signed affidavit/letter from the donor declaring the nature of the gift; 3) A bank statement showing a bank deposit of the donation.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Financial Investment', 'en', 'You have selected Financial investment as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A statement from your investment provider; 2) A bank statement displaying settlements from your investment provider; 3) Other statements or documents, proving investment profit from bonds, stocks, etc.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Inheritance', 'en', 'You have selected Inheritance as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) A copy of a will/testament; 2) A signed letter from the executor of the will (lawyer/solicitor/grant of probate).', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Mortgages/Loans', 'en', 'You have selected Mortgages/Loans as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send the following to complete your verification: A Mortgage/Loan contract, showing the mortgage or loan value and repayment plan AND a bank statement showing the loan/mortgage deposit into your account.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Salary', 'en', 'You have selected Salary as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us one or more of the following to complete your verification: 1) Payslips showing your income from at least the last month; 2) A bank statement showing salary payments from your employer for at least the last month; 3) A tax statement from the previous tax year.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW - Self-Employment Income', 'en', 'You have selected Self-employment as your main Source of Wealth, however the provided documentary evidence is not sufficient and does not meet our requirements. Please send us a tax statement from the previous tax year. Additionally, you can send us recent invoices/contracts/agreements for self-employed services or profit/loss statements, proving your monthly or annual income.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Higher Total Assets Value', 'en', 'We have identified a discrepancy in your overall wealth declaration. The documentary evidence provided indicates a significantly higher Total Assets value and does not correspond to the one you have declared with Binance. Please provide us with accurate information for your overall (approximate) total value of all owned assets and submit your application again. Providing incorrect, insufficient, or misleading information prevents the prompt approval of your application.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration - Significant Mistakes', 'en', 'After reviewing your declaration, we found significant errors. To ensure a speedy process, provide accurate and complete data for your annual income (gross), total assets, and sources of wealth. Please submit adequate evidence alongside your declaration. Incorrect or insufficient information will delay your application. Thank you for your cooperation.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) SOW Declaration -Employment Details Incorrect/Incomplete', 'en', 'We have identified incorrect, mismatching, or incomplete information on your Employment details declaration. Please resubmit your application with accurate information, including: 1) Employment status - current Employed/Self-employed/Student/Retired/Other status; 2) Employer/Business name - the name of your Employers Company/Business name; 3) Employer/Business address - registered Employer/Business address. Please ensure the information provided is up-to-date and that it matches the information provided in your documentary evidence.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Two or More Linked Bank Accounts', 'en', 'We have noticed the transfer of funds from your other bank account. Please send us a bank statement issued in the last 3 months, showing the transaction history of the other account (covering at least 1 month of transactions).', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
INSERT INTO kyc_core.message_map (code, lang, message, db_create_time, db_modify_time) VALUES('(EDD-1) Unclear Copy of Photo', 'en', 'The image quality of your photo is not clear and does not meet our visibility requirements. Please resubmit a copy in a higher resolution (at least 300 DPI) showing the full page with all four corners included in the frame. Alternatively, you can provide different documents to complete your verification.', '2023-06-25 18:05:20', '2023-06-25 18:05:20') ON DUPLICATE KEY UPDATE message = VALUES(message), db_create_time = VALUES(db_create_time), db_modify_time = VALUES(db_modify_time);
